test("precise local edit anchors can safely bypass whole-file read gate", () => {
  const count = load("_countOccurrences");
  const strip = load("_stripLineNoPrefix");
  const recover = load("_recoverEditMatch", { _stripLineNoPrefix: strip });
  const precise = load("_localEditHasPreciseAnchors", {
    _countOccurrences: count,
    _recoverEditMatch: recover,
  });
  const content = [
    ".hero {",
    "  color: red;",
    "}",
    ".cta {",
    "  color: blue;",
    "}",
    "",
  ].join("\n");

  assert.equal(precise(content, { type: "edit", oldString: "  color: red;", newString: "  color: green;" }), true);
  assert.equal(precise(content, { type: "edit", oldString: "  color:", newString: "  background:", replaceAll: false }), false);
  assert.equal(precise(content, { type: "edit", oldString: "  missing: true;", newString: "" }), false);
  // replace_all does NOT relax the uniqueness requirement. Uniqueness is the entire basis for
  // this bypass ("an exact, unique anchor is itself evidence the model is on the real bytes");
  // a 2-hit anchor is evidence of nothing, and granting the bypass here let an unread file be
  // rewritten at every occurrence. This assertion previously pinned that hole open.
  assert.equal(precise(content, { type: "edit", oldString: "  color:", newString: "  background:", replaceAll: true }), false);
  assert.equal(precise(content, {
    type: "multiedit",
    edits: [
      { old_string: "  color: red;", new_string: "  color: green;" },
      { old_string: "  color: blue;", new_string: "  color: white;" },
    ],
  }), true);
  assert.equal(precise(content, {
    type: "multiedit",
    edits: [
      { old_string: "  color:", new_string: "  background:" },
      { old_string: "  color: blue;", new_string: "  color: white;" },
    ],
  }), false);
  assert.match(extractFn("_executeToolStepInner"), /_localEditHasPreciseAnchors\(old, call\)/);
});

test("mutation paths reject relative traversal and unbound external targets", () => {
  const boundPaths = new Map([["/tmp/read-first.js", "/tmp/read-first.js"]]);
  const issue = load("_mutationPathIssue", {
    _normalizeFsPath: NORMALIZE_PATH,
    _coherentFilePath: COHERENT_PATH,
    _resolveRel: (path) => NORMALIZE_PATH("/repo/" + path),
    _pathIdentity: PATH_IDENTITY,
    _allRoots: () => ["/repo"],
    _boundRunFilePath: (_run, _root, path) => boundPaths.get(path) || "",
  });
  assert.match(issue("../outside.js", "/outside.js", "/repo", {}), /逃出当前工作区/);
  assert.match(issue("/tmp/new.js", "/tmp/new.js", "/repo", {}), /不在本次运行/);
  assert.equal(issue("/tmp/read-first.js", "/tmp/read-first.js", "/repo", {}), "");
  assert.match(issue("/tmp/read-first.js", "/tmp/read-first.js", "/repo", {}, false), /不在本次运行/);
});

test("a successful structured write records its new content as the current readable version", () => {
  const norm = NORM_REL;
  const signature = load("_contentSignature");
  const recordRange = load("_recordRunReadRange", { _normRel: norm });
  const recordKnown = load("_recordRunKnownContent", {
    _normRel: norm,
    _contentSignature: signature,
    _recordRunKnownSignature: load("_recordRunKnownSignature", { _normRel: norm }),
  });
  const hasCurrentRead = load("_runHasCurrentRead", {
    _normRel: norm,
    _contentSignature: signature,
  });
  const knownRanges = load("_knownReadRanges", { _normRel: norm, _mergeReadRanges: load("_mergeReadRanges") });
  const run = { ctx: { filesRead: new Set() } };
  const written = "export const value = 2;\nexport default value;\n";

  assert.equal(recordKnown(run, "/repo", written, "src/value.js", "/repo/src/value.js"), true);
  assert.equal(hasCurrentRead(run, "/repo", written, "src/value.js"), true);
  assert.equal(hasCurrentRead(run, "/repo", written, "/repo/src/value.js"), true);
  assert.deepEqual(knownRanges(run, "/repo", signature(written), 2, "src/value.js"), [],
    "a just-written version may authorize safe follow-up edits, but must not masquerade as model-visible read coverage");
  assert.equal(run.ctx.filesRead.has("src/value.js"), false,
    "write-known content should not tell the agent it has re-read the file body");
  assert.equal(
    hasCurrentRead(run, "/repo", "export const value = 3;\nexport default value;\n", "src/value.js"),
    false,
    "a later external change must still invalidate the known version",
  );
});

test("same-response reads and fuzzy bindings cannot authorize mutations before the model sees their results", () => {
  const signature = load("_contentSignature");
  const recordRange = load("_recordRunReadRange", { _normRel: NORM_REL });
  const hasCurrentRead = load("_runHasCurrentRead", { _normRel: NORM_REL, _contentSignature: signature });
  const bind = load("_bindRunFilePath", { _normRel: NORM_REL, _coherentFilePath: COHERENT_PATH });
  const bound = load("_boundRunFilePath", { _normRel: NORM_REL });
  const freshBinding = load("_sameBatchRunFilePathBinding", { _normRel: NORM_REL });
  const content = "one\ntwo\n";
  const run = { ctx: { filesRead: new Set() }, _toolBatch: 1 };

  assert.equal(recordRange(run, "/repo", 1, 2, 2, signature(content), "a.js", "/repo/a.js"), true);
  bind(run, "/repo", "wrong/a.js", "/repo/packages/a.js");
  assert.equal(hasCurrentRead(run, "/repo", content, "a.js"), false, "a read from this model response cannot unlock its write");
  assert.equal(bound(run, "/repo", "wrong/a.js"), "", "a fuzzy path learned this response cannot drive delete/move yet");
  assert.equal(freshBinding(run, "/repo", "wrong/a.js"), "/repo/packages/a.js",
    "the mutation guard must still see the fresh binding instead of falling back to the wrong requested path");
  assert.match(extractFn("_executeToolStepInner"), /const sameBatchSourceBinding = _sameBatchRunFilePathBinding[\s\S]{0,1600}已阻止退回原始路径写错文件/);
  // 新文件豁免：拦截必须以「目标在磁盘上真实存在」为前提，全新创建不能被同批绑定拦死。
  assert.match(extractFn("_executeToolStepInner"),
    /const sameBatchTargetExists = !!sameBatchBinding\s*&& \(\(await _pathExistsAsFile\(sameBatchTargetAbs\)\) \|\| \(await _pathExistsAsDir\(sameBatchTargetAbs\)\)\)/,
    "写入门禁只拦磁盘上已存在的目标，新文件创建必须放行");
  // 仅在真发生模糊路径纠正时才拦：同一回复里 read+edit 同一文件（精确路径）不能被误拦。
  assert.match(extractFn("_executeToolStepInner"),
    /if \(sameBatchBinding && sameBatchTargetExists && _wasFuzzyCorrected\)/,
    "读取门只在真发生模糊路径纠正时才拦，精确 read+edit 同文件必须放行");

  run._toolBatch = 2;
  assert.equal(hasCurrentRead(run, "/repo", content, "a.js"), true);
  assert.equal(bound(run, "/repo", "wrong/a.js"), "/repo/packages/a.js");
  assert.equal(freshBinding(run, "/repo", "wrong/a.js"), "");
});

test("写入门禁条件矩阵：陈旧批号绑定过期放行，同批真实绑定仍拦，上一批绑定不拦", () => {
  const bind = load("_bindRunFilePath", { _normRel: NORM_REL, _coherentFilePath: COHERENT_PATH });
  const freshBinding = load("_sameBatchRunFilePathBinding", { _normRel: NORM_REL });
  const run = { _toolBatch: 1 };

  // 同批刚学到的绑定（批号 == 当前批）：写入门禁必须看得到 → 已存在文件维持拦截。
  bind(run, "/repo", "src/db.js", "/repo/packages/api/db.js");
  assert.equal(freshBinding(run, "/repo", "src/db.js"), "/repo/packages/api/db.js");

  // 有界等待（方案 B）：绑定批号领先当前批号超过 2 批 = 批号计数器被重置过的残留表，
  // 按过期放行——否则全新 run 里每一批写入都会被它拦死（截图里的成批零落盘）。
  bind(run, "/repo", "tsconfig.json", "/repo/tsconfig.json", 9);
  assert.equal(freshBinding(run, "/repo", "tsconfig.json"), "", "批号计数器重置后的陈旧绑定必须过期放行");
  // 临界：领先不足 3 批仍算同批（保守侧，不误放正常同批绑定）。
  bind(run, "/repo", "vite.config.ts", "/repo/vite.config.ts", 3);
  assert.equal(freshBinding(run, "/repo", "vite.config.ts"), "/repo/vite.config.ts");

  // 上一批完成的绑定（批号 < 当前批）：模型已看到读取结果，不再等待。
  run._toolBatch = 2;
  assert.equal(freshBinding(run, "/repo", "src/db.js"), "");
});

test("hard_blocked/authorized 读取在覆盖重放里等价于读取完成，写入门禁不再死等", () => {
  const signature = load("_contentSignature");
  const recordRange = load("_recordRunReadRange", { _normRel: NORM_REL });
  const hasCurrentRead = load("_runHasCurrentRead", { _normRel: NORM_REL, _contentSignature: signature });
  const sync = load("_syncRunReadCoverageFromMessages", {
    _recordRunReadRange: recordRange,
    _resolveRel: (path, root) => NORMALIZE_PATH(root + "/" + path),
  });
  const content = "a\nb\nc\n"; // 3 行
  const sig = signature(content);
  const run = { ctx: { filesRead: new Set() }, _toolBatch: 3 };
  sync(run, "/repo", [
    // 重复读硬拦截存根：to 是请求区间末行，可越过文件末尾（这里 5 > 3）。
    { role: "tool", _ideMeta: { kind: "read", resultKind: "hard_blocked", canonicalPath: "src/app.js", signature: sig, from: 1, to: 5, total: 3, complete: false } },
    { role: "tool", _ideMeta: { kind: "read", resultKind: "authorized", canonicalPath: "src/other.js", signature: sig, from: 1, to: 3, total: 3, complete: true } },
    // 失败/未知结果仍不计入覆盖。
    { role: "tool", _ideMeta: { kind: "read", resultKind: "error", canonicalPath: "src/broken.js", signature: sig, from: 1, to: 3, total: 3 } },
  ]);
  assert.equal(run.ctx.filesRead.has("src/app.js"), true, "hard_blocked 语义是原文已在上文，重放后覆盖不能丢");
  assert.equal(run.ctx.filesRead.has("src/other.js"), true);
  assert.equal(run.ctx.filesRead.has("src/broken.js"), false);
  assert.equal(run._readSeen.get("/repo/src/app.js"), 3, "hard_blocked 的 to 要钳到 total");
  // 下一批里这份覆盖就能授权写入（死锁断开）；同批内仍不能。
  assert.equal(hasCurrentRead(run, "/repo", content, "src/app.js"), false);
  run._toolBatch = 4;
  assert.equal(hasCurrentRead(run, "/repo", content, "src/app.js"), true);
});

test("重复读硬拦截返回前刷新路径绑定，写入门禁不再等一个不会再来的读取结果", () => {
  // 结构断言：hard_blocked 返回前必须绑定路径，且批号沿用覆盖完成时的批号（上一轮
  // 读完的写入即刻放行；本批才读完的仍算同批读写）。
  assert.match(extractFn("_executeToolStepInner"),
    /const _hbState = _readCoverageStateFor\(run, root, _sig, total, call\.path, usedPath\);\s*_bindRunFilePath\(run, root, call\.path, usedPath \|\| call\.path, _hbState\?\.completedBatch \|\| 0\);\s*return \{\s*type: "read", path: call\.path, content: _hardBlockMsg/,
    "hard_blocked 返回前必须用覆盖完成批号刷新绑定");
  // 行为断言：用覆盖完成批号（上一批）绑定不会被写入门禁看成同批等待。
  const bind = load("_bindRunFilePath", { _normRel: NORM_REL, _coherentFilePath: COHERENT_PATH });
  const freshBinding = load("_sameBatchRunFilePathBinding", { _normRel: NORM_REL });
  const run = { _toolBatch: 5 };
  bind(run, "/repo", "src/app.js", "/repo/src/app.js", 4); // 覆盖在第 4 批完成
  assert.equal(freshBinding(run, "/repo", "src/app.js"), "", "上一轮读完的 hard_blocked 后写入必须放行");
  bind(run, "/repo", "src/live.js", "/repo/src/live.js", 5); // 本批才读完
  assert.equal(freshBinding(run, "/repo", "src/live.js"), "/repo/src/live.js", "本批才读完的仍算同批读写、维持等待");
});

test("ordered tool segments preserve mutation barriers while parallelizing only adjacent reads", async () => {
  const schedule = load("_runOrderedToolSegments");
  const events = [];
  let disk = "old";
  const items = [{ type: "write" }, { type: "read" }, { type: "read" }, { type: "command" }, { type: "read" }];
  let activeReads = 0;
  let maxReads = 0;
  await schedule(
    items,
    (item) => item.type === "read",
    async (item, index) => {
      if (item.type === "write") { disk = "new"; events.push("write"); return; }
      if (item.type === "command") { events.push("command"); return; }
      activeReads++;
      maxReads = Math.max(maxReads, activeReads);
      await new Promise((resolve) => setImmediate(resolve));
      events.push(`read${index}:${disk}`);
      activeReads--;
    },
  );
  assert.deepEqual(events.slice(0, 3).sort(), ["read1:new", "read2:new", "write"].sort());
  assert.ok(events.indexOf("write") < events.indexOf("read1:new"), "write before read must not be reordered");
  assert.ok(events.indexOf("read2:new") < events.indexOf("command"));
  assert.ok(events.indexOf("command") < events.indexOf("read4:new"));
  assert.equal(maxReads, 2, "adjacent reads still execute in parallel");

  // 现实校准波：同批的 list 自成 "recon" 段先落地，随后读取才并行——外部清空目录时
  // 同批脏读被空根标记短路，不再并发撞 cannot stat。
  assert.match(SRC, /it\.call\.type === "list" \? "recon" : "read"/,
    "同批 list 必须先于读取落地");

  const parallel = load("_isReadOnlyParallel", {
    _READ_ONLY_TYPES: new Set(["read"]),
    _dbCallMayMutate: (call) => String(call?.driver || "").toLowerCase() === "redis"
      ? !/^(?:GET|HGETALL)\b/i.test(String(call?.query || ""))
      : !/^\s*(?:select|show|describe|desc)\b/i.test(String(call?.query || "")),
  });
  assert.equal(parallel({ type: "genimage", dest: "same.png" }), false, "asset writes must remain ordered");
  assert.equal(parallel({ type: "db", query: "WITH old AS (DELETE FROM jobs RETURNING *) SELECT * FROM old" }), false,
    "writable CTEs must not enter a parallel read segment");
  assert.equal(parallel({ type: "db", driver: "redis", query: "GET key" }), true);
  assert.equal(parallel({ type: "db", driver: "redis", query: "SET key value" }), false);
});

test("adjacent run_worker calls execute as a parallel segment, still barriered from reads", async () => {
  const schedule = load("_runOrderedToolSegments");
  const events = [];
  let activeWorkers = 0;
  let maxWorkers = 0;
  const items = [
    { kind: "read" }, { kind: "read" },
    { kind: "worker" }, { kind: "worker" }, { kind: "worker" },
    { kind: "read" },
  ];
  await schedule(
    items,
    (item) => (item.kind === "read" ? "read" : item.kind === "worker" ? "worker" : ""),
    async (item, index) => {
      if (item.kind === "worker") {
        activeWorkers++;
        maxWorkers = Math.max(maxWorkers, activeWorkers);
        await new Promise((resolve) => setImmediate(resolve));
        events.push(`worker${index}`);
        activeWorkers--;
        return;
      }
      events.push(`read${index}`);
    },
  );
  assert.equal(maxWorkers, 3, "同轮相邻的 worker 必须真并行（此前被当硬屏障串行跑）");
  assert.ok(events.indexOf("read1") < events.indexOf("worker2"), "读段先于 worker 段");
  assert.ok(events.indexOf("worker4") < events.indexOf("read5"), "worker 段完成后才轮到后续读");
});

test("Michael Design 技术栈只有一个权威定义，且和真实上线站点一致", () => {
  // 事实来源是 owner 真正上线的站点（package "michael-ide-site"）：
  // Vite 7 + React 19 + TS 5.9 + Tailwind v4(@tailwindcss/vite, CSS-first) + shadcn/ui
  // (Radix + CVA + clsx + tailwind-merge 的 cn() + lucide-react)，且项目里没有
  // tailwind.config.* / postcss.config.js / postcss / autoprefixer。
  const rule = SRC.slice(SRC.indexOf("const _MD_STACK_RULE"), SRC.indexOf("const _AGENT_ROLE_BLOCKS"));
  assert.ok(rule, "必须有唯一权威的 _MD_STACK_RULE");
  for (const must of ["React 19", "TypeScript", "Tailwind v4", "shadcn/ui",
                      "@tailwindcss/vite", "class-variance-authority", "tailwind-merge",
                      "clsx", "lucide-react", "@radix-ui/react-", "cn()"]) {
    assert.ok(rule.includes(must), `权威栈缺少真实站点确实在用的：${must}`);
  }
  // 最关键的否定规则：真实站点里根本没有这些文件/依赖，建了就是另一套项目
  assert.match(rule, /不要】新建 tailwind\.config/, "必须明确禁止建 tailwind.config（v3 做法）");
  assert.ok(rule.includes("postcss") && rule.includes("autoprefixer"),
    "必须明确不要装 postcss/autoprefixer——真实站点一个都没有");
  // sonner 在 package.json 里但 src/ 零引用，属于死依赖，不得写进房屋标准
  assert.ok(!rule.includes("sonner"), "sonner 是真实站点里的死依赖（零 import），不得写进标准栈");

  // 各处必须引用同一份，不再各说各话
  for (const site of ["从零网站技术栈律：\" : \"技术栈律：\") + _MD_STACK_RULE", "从零网站技术栈硬约束：\" + _MD_STACK_RULE",
                      "- ${_MD_STACK_RULE}"]) {
    assert.ok(SRC.includes(site.replace('\\"', '"')) || SRC.includes(site),
      `声明点必须引用权威常量而不是自己复述一遍：${site}`);
  }
  // Vue 不得再作为等价默认出现在实现指令里
  assert.doesNotMatch(SRC, /用 React\/Vue \+ Tailwind 写组件化代码/,
    "选完设计方向后的实现提示不得把 Vue 当作等价选项");
  assert.doesNotMatch(SRC, /技术取向一律上现代框架\(Vue3\+Vite/,
    "设计调研提示不得把 Vue3 排在 React 前面");

  // 声明与执行必须一致：web_scaffold 默认框架
  assert.match(SRC, /framework: String\(args\.framework \|\| "react"\)/,
    "web_scaffold 默认必须是 react——默认 vue 会让模型照着 React 提示却拿到 Vue 项目");
});

test("技术栈规则必须真的送达模型——每个 UI 轮次，包括网关设计层在场时", () => {
  // 上一版的教训：规则写好了却送不到。_uiDesignCraftBlock 在网关设计层在场时会提前
  // return 省 token，而承载栈规则的 greenfieldRule 在 return 之后才拼装；同时另一个
  // 承载点只在 greenfield 时触发，于是 agent 建完第一个文件之后就再也收不到。
  // 这个测试不看源码文本，直接跑真实函数看输出里有没有栈规则。
  const STACK = "[[MD_STACK_SENTINEL]]";
  const craft = load("_uiDesignCraftBlock", {
    _MD_STACK_RULE: STACK,
    _uiDesignReferenceRule: () => "",
    _uiDesignTransactionalRule: () => "",
    _uiStructuralSignal: () => "",
  });
  const mkFrame = (profile) => load("_agentDecisionFrameBlock", {
    _MD_STACK_RULE: STACK,
    _engineeringProfileWithAiIntent: () => profile,
    _agentBugEvidenceLadderBlock: () => "",
    _agentIntentExecutionBlock: () => "",
    _uiStructuralSignal: () => "",
  });

  // ① 网关设计层在场（默认安装的常态）——省 token 也不能把栈规则省掉
  const lean = craft("做个官网", { ui: true, uiProject: true, fromZeroUiProject: true },
    { serverDesignLayersActive: true });
  assert.ok(lean.includes(STACK), "精简分支必须仍然带栈规则——这正是上一版丢失的地方");

  // ② 完整分支同样带
  const full = craft("做个官网", { ui: true, uiProject: true, fromZeroUiProject: true },
    { serverDesignLayersActive: false });
  assert.ok(full.includes(STACK), "完整分支必须带栈规则");

  // ③ 决策框架：greenfield 与「已有项目」都要带——agent 写完第一个文件后就不再是
  //    greenfield，而那正是它开始违反规则的时刻
  const green = mkFrame({ ui: true, uiProject: true, fromZeroUiProject: true })("做个官网");
  assert.ok(green.includes(STACK), "greenfield 轮必须带栈规则");
  const existing = mkFrame({ ui: true, uiProject: true, fromZeroUiProject: false })("继续完善这个官网");
  assert.ok(existing.includes(STACK),
    "已有项目的 UI 轮同样必须带栈规则——否则第二轮起就没人管它用什么栈了");

  // ④ 非 UI 轮不应该被塞进来
  const backend = craft("修后端接口", { ui: false, uiProject: false }, { serverDesignLayersActive: true });
  assert.ok(!backend.includes(STACK), "非 UI 轮不注入栈规则");
});

test("知识库检索结果必须把 v3 蓝本翻译成 v4，而不是让模型照抄", () => {
  // 真正的成因：模型自己调 knowledge_search，IDE 把 3 段 Tailwind v3 蓝本原样回灌，
  // 还写着「照这个来做」。三份可复制粘贴的 tailwind.config.js 例子会压过提示词里
  // 一句禁令——模型于是建了 postcss.config.js + tailwind.config.js。
  const i = SRC.indexOf("📚 专业知识库");
  assert.ok(i > 0, "知识库结果格式化位置必须存在");
  const block = SRC.slice(i, i + 1400);
  assert.match(block, /构建配置不要照抄/, "必须明确告诉模型构建配置不能照抄");
  assert.match(block, /@theme inline/, "必须给出 v4 的等价写法");
  assert.ok(block.includes("tailwind.config") && block.includes("postcss"),
    "必须点名 v3 里会出现、但本栈禁止的那些文件");
  // 「照这个来做」只能适用于视觉判断，不能笼统适用于全部内容
  assert.match(block, /视觉判断（[^）]*）照这个来做/,
    "「照这个来做」必须限定在视觉判断上，构建配置另有规矩");
});

test("别的栈只搬令牌，绝不把项目迁成 React", () => {
  const rule = SRC.slice(SRC.indexOf("const _MD_STACK_RULE"), SRC.indexOf("const _AGENT_ROLE_BLOCKS"));
  // 三个分支：没点名 -> 原生直接建；已有别的栈 -> 保留原栈只搬语义；不需要转换就别转换
  assert.match(rule, /保留人家原来的栈/, "已有别的栈必须保留，不得改写");
  assert.match(rule, /不要改写成 React/, "必须明确禁止迁移到 React");
  assert.match(rule, /不要在旁边另起一个 React 前端/, "也不得绕道另起 React 前端");
  assert.ok(rule.includes("Django") && rule.includes("Flask"),
    "必须点名服务端渲染栈——Python 项目正是 owner 举的例子");
  assert.match(rule, /shadcn-vue/, "Vue 项目要用 shadcn-vue 而不是 React 版");
  assert.match(rule, /不需要转换就别转换/, "已经是本栈的项目不得做任何迁移动作");

  // 反向断言：那条把「和 React 不兼容」当唯一免转理由的escape clause必须消失。
  // 它读起来是「只要能上 React 就该转」，Django 恰恰能上 React —— 正好授权了被禁止的迁移。
  assert.doesNotMatch(SRC, /已有技术栈与 React 不兼容时才例外/,
    "这条反向条款会授权 Python→React 迁移，必须删除而不是软化");
  assert.doesNotMatch(SRC, /已有项目技术栈不兼容时才例外/, "同上，_uiDesignCraftBlock 那份也要删");
});

