  assert.equal(isWeak("gpt-4o-mini"), true);
  assert.equal(isWeak("gemini-2.0-flash"), true);
  assert.equal(isWeak("qwen2.5-7b-instruct"), true);
  assert.equal(isWeak("llama-3.2-1.5b"), true);
  // 大模型不误伤
