// ── write_file/edit_file 流式参数解析节流（"写内容时 IDE 卡死"的根因）─────────
// 旧门槛只有 args.endsWith("}")。散文里成立，但这里流的是源代码，代码里到处是 `}`，
// 于是大量 delta 都会命中，对越滚越大的缓冲区全量 JSON.parse → O(n²)。
test("流式参数解析：代码内容频繁以 } 结尾时必须被节流", () => {
  const INTERVAL = 250;
  // 复刻 _mayAttemptArgsParse 的判定逻辑（纯函数，便于在 node 下验证行为）。
  function mayAttempt(entry, now) {
    const args = entry.args || "";
    if (!args.trimEnd().endsWith("}")) return false;
    if (entry._argsParseAt && now - entry._argsParseAt < INTERVAL) return false;
    entry._argsParseAt = now;
    return true;
  }
  const entry = { args: "" };
  let attempts = 0;
  // 模拟流式写入一个 JS 文件：每个 delta 都以 `}` 收尾（真实代码的常见形态）。
  let t = 1_000_000;
  for (let i = 0; i < 400; i++) {
    entry.args += `function f${i}(){ return ${i}; }`;
    t += 5; // 每 5ms 一个 delta
    if (mayAttempt(entry, t)) attempts++;
  }
  // 400 个 delta、总跨度 2000ms：不节流会是 400 次全量 parse；节流后应 ≤ 10 次。
  assert.ok(attempts <= 10, `parse 尝试次数应被节流，实际 ${attempts}`);
  assert.ok(attempts >= 1, "至少要尝试一次，否则文件名/预览永远出不来");
});

test("流式参数解析：不以 } 结尾时不尝试 parse", () => {
  const entry = { args: '{"path":"a.js","content":"const x = 1' };
  function mayAttempt(e, now) {
    const args = e.args || "";
    if (!args.trimEnd().endsWith("}")) return false;
    if (e._argsParseAt && now - e._argsParseAt < 250) return false;
    e._argsParseAt = now;
    return true;
  }
  assert.equal(mayAttempt(entry, Date.now()), false);
});

// A suggestion chip's text is sent verbatim back to the agent when clicked, so corrupting it
// corrupts the next instruction. The old blanket /\*+/g strip ate the asterisk in
// `SELECT * FROM price_history;`, turning a valid query into a broken one on screen and in
// the reply. Emphasis is markup only OUTSIDE code spans.
test("_detectChoiceOptions keeps asterisks inside code spans", () => {
  const _stripEmphasisOutsideCode = load("_stripEmphasisOutsideCode");
  const detect = load("_detectChoiceOptions", { _stripEmphasisOutsideCode });

  const answer = [
    "你可以自己试试",
    "",
    "1. **改个价格提醒**: 去 `config.yaml` 把目标价调高，然后 `--once` 跑一次",
    '2. **看历史数据**: 跑几次后用 `sqlite3 price_history.db "SELECT * FROM price_history;"` 看看存了什么',
    "",
    "需要我帮你调试抓价格的部分吗？",
  ].join("\n");

  const opts = detect(answer);
  assert.ok(opts, "two numbered suggestions plus a question cue should parse as choices");
  assert.equal(opts.length, 2);

  // The bold markers are markup and must go...
  assert.ok(!opts[0].text.includes("**"), "markdown bold should be stripped");
  assert.ok(opts[0].text.startsWith("改个价格提醒"));

  // ...but the asterisk inside the backticked query is CONTENT and must survive, both in the
  // visible label and in the text sent back on click.
  assert.ok(opts[1].text.includes("SELECT * FROM price_history;"), `lost the asterisk: ${opts[1].text}`);
  assert.ok(opts[1].send.includes("SELECT * FROM price_history;"), `send payload corrupted: ${opts[1].send}`);
});

test("_stripEmphasisOutsideCode only strips outside backticks", () => {
  const strip = load("_stripEmphasisOutsideCode");
  assert.equal(strip("**bold** and `a * b`"), "bold and `a * b`");
  assert.equal(strip("no code, **bold**"), "no code, bold");
  assert.equal(strip("`* leading`"), "`* leading`");
  assert.equal(strip(""), "");
});

// ---- hot-exit buffer recovery must never revert a file that disk has moved past ----
//
// The recovery path re-applies unsaved editor buffers saved on beforeunload. It used to do so
// unconditionally, which turned "restore my unflushed edits" into "revert the file" whenever
// anything had written the path in between (a save that did land, git checkout, another
// window, the agent). Autosave then pushed the reverted buffer to disk, so it was real data
// loss, not just a stale view.
test("_bufferBaseStamp fingerprints disk content deterministically", () => {
  const stamp = load("_bufferBaseStamp");
  assert.equal(stamp("hello"), stamp("hello"), "same content must produce the same stamp");
  assert.notEqual(stamp("hello"), stamp("hello "), "trailing whitespace must change the stamp");
  assert.notEqual(stamp("hello"), stamp("olleh"), "reordering must change the stamp");
  assert.notEqual(stamp(""), stamp("a"));
  assert.equal(stamp(null), null, "a file with no known disk baseline has no stamp");
  assert.equal(stamp(undefined), null);
  assert.match(stamp("abc"), /^3:[0-9a-z]+$/, "stamp carries the length so a hash tie still differs on size");
});

test("hot-exit recovery gates on the disk baseline before re-applying a buffer", () => {
  const src = extractFn("restoreSession");

  // The captured baseline must be compared against the CURRENT disk content, and a mismatch
  // must skip the entry rather than fall through to the write.
  assert.match(src, /u\.base !== _bufferBaseStamp\(f\.diskContent\)/,
    "restore must compare the stored baseline against freshly-read disk content");
  const gate = src.indexOf("staleSkipped++");
  const write = src.indexOf("_setModelValueProgrammatically(f.model, u.content)");
  assert.ok(gate > -1 && write > -1, "both the staleness gate and the apply must exist");
  assert.ok(gate < write, "the staleness gate must run BEFORE the buffer is applied");

  // Recovery must not look like user typing; the raw setValue scheduled an autosave of the
  // very content we are unsure about.
  assert.ok(!/\bf\.model\.setValue\(u\.content\)/.test(src),
    "recovery must not use raw setValue — it bypasses _programmaticModelUpdates and triggers autosave");

  // Capture side must actually record the baseline, or the gate above is inert.
  const capture = extractFn("_flushDirtyBuffersSync");
  assert.match(capture, /base: _bufferBaseStamp\(f\.diskContent\)/,
    "the beforeunload capture must stamp each buffer with its disk baseline");
});

// ---- no undeclared identifiers anywhere in client code ----
//
// This class of bug bit four separate times, always the same way: a `const` declared inside a
// `for`/`try`/`if` block and then read after that block closed. It is invisible to review and
// to the type-free runtime until the line executes, at which point WebKit throws
// "Can't find variable: X" — which the agent executor catches and renders as a red badge,
// silently killing every statement after it.
//
// Real instances found in production code:
//   * `fp`                  — killed the read_file failure handler, which disabled the entire
//                             progressive anti-guessing gate (the model could guess paths forever)
//   * `_top`                — killed the workspace preheat listing, whose whole purpose is to
//                             stop the model guessing filenames
//   * `_steerSemanticText`  — killed mid-run steering after the message was already queued
//   * `session`             — killed the background-task monitor at its first line
//   * `chatSessions`        — silently disabled the "view task" button (swallowed by try/catch)
//
// Scope analysis catches all of them statically, so this asserts there are none left.
test("client modules have no undeclared identifiers", async () => {
  const { analyze } = createRequire(import.meta.url)("eslint-scope");

  // Genuine runtime globals. Anything NOT here that fails to resolve is a bug.
  const GLOBALS = new Set([
    // ECMAScript
    "Array","ArrayBuffer","Boolean","DataView","Date","Error","Float32Array","Infinity","Int16Array",
    "Intl","JSON","Map","Math","NaN","Number","Object","Promise","Proxy","RangeError","RegExp","Set",
    "String","Symbol","Uint32Array","Uint8Array","WeakMap","WeakSet","globalThis","isNaN","parseFloat",
    "parseInt","structuredClone","undefined","decodeURIComponent","encodeURIComponent",
    // DOM / browser
    "AbortController","AbortSignal","Blob","BroadcastChannel","CSS","CustomEvent","Event","FileReader",
    "FormData","Image","MutationObserver","Node","Notification","PerformanceObserver","ResizeObserver",
    "TextDecoder","TextEncoder","URL","URLSearchParams","alert","cancelAnimationFrame","clearInterval",
    "clearTimeout","confirm","console","crypto","document","fetch","localStorage","location","navigator",
    "performance","queueMicrotask","requestAnimationFrame","requestIdleCallback","self","setInterval",
    "setTimeout","window","setImmediate",
    // Feature-detected on purpose, always behind `typeof x !== "undefined"`
    "module","session",
  ]);

  const FILES = ["src/main.js","src/tool-guides.js","src/markdown.js","src/conversation-memory.js","src/growth.js","src/i18n.js"];
  const offenders = [];
  for (const file of FILES) {
    const code = readFileSync(join(HERE, "..", file), "utf8");
    const ast = acorn.parse(code, { ecmaVersion: "latest", sourceType: "module", ranges: true, locations: true });
    const scope = analyze(ast, { ecmaVersion: 2024, sourceType: "module" });
    for (const ref of scope.globalScope.through) {
      const name = ref.identifier.name;
      if (GLOBALS.has(name)) continue;
      offenders.push(`${file}:${ref.identifier.loc.start.line}  ${name}`);
    }
  }
  assert.deepEqual(offenders, [],
    `undeclared identifier(s) — these throw ReferenceError the moment the line runs:\n  ${offenders.join("\n  ")}`);
});

// The `typeof`-guarded names above are only safe BECAUSE of the guard. If someone drops the
// guard, the allowlist would hide a real ReferenceError, so pin the guard itself.
test("typeof-guarded globals keep their guards", () => {
  const code = readFileSync(join(HERE, "../src/main.js"), "utf8");
  for (const [name, expected] of [["session", 3], ["module", 1]]) {
    const guards = code.match(new RegExp(`typeof\\s+${name}\\s*!==?\\s*["']undefined["']`, "g")) || [];
    assert.ok(guards.length >= expected,
      `${name} is allowlisted as a feature-detected global but only ${guards.length} typeof guard(s) remain (expected >= ${expected})`);
  }
});

// ---- one 「接下来」 block per turn ----
//
// An answer that offers options used to render its own panel under a 👉 banner, stacked above
// a second panel of run-state suggestions under its own heading. Two lists, two headings, both
// answering "what next". They now merge into a single block, and the banner is gone.
test("offered choices and run-state suggestions merge into one 接下来 block", () => {
  const mkEl = (tag) => {
    const el = {
      tagName: tag, className: "", dataset: {}, children: [], textContent: "", innerHTML: "",
      classList: {
        _s: new Set(),
        add(c) { this._s.add(c); }, contains(c) { return el.className.split(/\s+/).includes(c) || this._s.has(c); },
      },
      appendChild(c) { el.children.push(c); return c; },
      remove() {},
      addEventListener() {},
      querySelector() { return mkEl("span"); },
      querySelectorAll(sel) {
        const want = sel.replace(".", "");
        return el.children.filter((c) => String(c.className).split(/\s+/).includes(want));
      },
      get lastElementChild() { return el.children[el.children.length - 1] || null; },
    };
    return el;
  };
  const container = mkEl("div");
  const sess = { container };
  const deps = {
    document: { createElement: mkEl },
    _NS_SPARK: "<svg/>", _NS_ARROW: "<svg/>", _NEXT_STEPS_MAX: 4,
    sendPrompt() {}, _currentSession: () => null, _chatFollow() {},
  };
  const render = load("_renderSuggestionChips", deps);

  // Turn renders offered choices first...
  render(sess, [{ label: "1、爬个电商网站", send: "我选 1" }, { label: "2、批量爬多页", send: "我选 2" }], "接下来 ›");
  assert.equal(container.children.length, 1, "first call creates the block");
  const block = container.children[0];
  assert.equal(block.className, "next-steps");
  assert.equal(block.querySelectorAll(".next-steps__chip").length, 2);

  // ...then run-state suggestions merge into the SAME block rather than adding a second one.
  render(sess, [{ label: "继续完成剩余部分", send: "继续" }], "接下来 ›");
  assert.equal(container.children.length, 1, "second call must NOT create a second panel");
  assert.equal(block.querySelectorAll(".next-steps__chip").length, 3, "chips accumulate in one block");

  // Exactly one heading, added only by the call that created the block.
  assert.equal(block.querySelectorAll(".next-steps__label").length, 1, "one heading, not two");

  // The shared cap holds across both sources.
  render(sess, [{ label: "a", send: "a" }, { label: "b", send: "b" }, { label: "c", send: "c" }], "接下来 ›");
  assert.equal(block.querySelectorAll(".next-steps__chip").length, 4, "total capped at _NEXT_STEPS_MAX");
});

test("the 👉 click-to-reply banner is gone", () => {
  assert.ok(!SRC.includes("点一个直接回复"), "the 👉 banner text must not be reintroduced");
  assert.ok(!/className = "ai-choices"/.test(SRC), "the separate choice panel must not come back");
  assert.match(extractFn("_maybeRenderChoices"), /_renderSuggestionChips\(/,
    "offered choices must render through the 接下来 renderer");
});

// ---- custom models: one endpoint, many model names ----
//
// A relay endpoint typically exposes a dozen models behind one base URL + key. Entering them
// one at a time meant retyping the URL and key for each. The name field now splits on , and ;
// — including the full-width ，； a Chinese IME actually produces, which is what this field
// gets typed with in practice.
test("custom-model name field splits on ASCII and full-width separators", () => {
  const SAVE = extractFn("showCustomModelsDialog");

  // The parse must handle both ASCII and full-width separators, and dedupe.
  const split = (v) => [...new Set(v.split(/[,;，；]/).map((x) => x.trim()).filter(Boolean))];
  assert.deepEqual(split("gpt-4o-mini"), ["gpt-4o-mini"]);
  assert.deepEqual(split("a,b;c"), ["a", "b", "c"]);
  assert.deepEqual(split("a，b；c"), ["a", "b", "c"], "full-width , and ; must split too");
  assert.deepEqual(split(" a , , b "), ["a", "b"], "blank segments dropped");
  assert.deepEqual(split("a,a,b"), ["a", "b"], "duplicates collapsed");
  assert.deepEqual(split(",;，；"), [], "separators only => nothing to add");

  // And the shipped code must actually use that split, not the old single-value read.
  assert.match(SAVE, /inName\.value\.split\(\/\[,;，；\]\/\)/,
    "the save handler must split the name field");
  assert.ok(!/const name = inName\.value\.trim\(\);/.test(SAVE),
    "the old single-name read must be gone");

  // Editing with several names keeps the edited row and appends the rest, rather than
  // silently discarding the extras.
  assert.match(SAVE, /name: names\[0\]/, "edited row takes the first name");
  assert.match(SAVE, /names\.slice\(1\)/, "remaining names are appended when editing");

  // The 64-entry cap still holds, and over-cap input is reported instead of vanishing.
  assert.match(SAVE, /items\.length >= 64/, "cap must still be enforced");
  assert.match(SAVE, /未添加/, "dropped-over-cap entries must be surfaced to the user");
});

test("custom-model dialog has no empty-state placeholder", () => {
  assert.ok(!SRC.includes("还没有自定义模型"),
    "the redundant empty-state copy must not come back");
  assert.match(extractFn("showCustomModelsDialog"), /if \(!items\.length\) return;/,
    "an empty list should render nothing at all");
});

// ---- the follow-up reply must survive the turn ----
//
// _agentFollowUp answers a file read. The file bodies it reasons over are sent in an ephemeral
// context message that is deliberately NOT persisted (a single read can be ~55k chars), so its
// reply is the only durable trace of what the file actually contained.
//
// It used to push that reply onto `sess.memory.assemble()`, which returns a freshly-built array
// (conversation-memory.js assembledSlice: `const result = []; … return result;`). The push
// mutated a temporary and vanished. The next turn therefore saw "[TOOL:read_file] <path>" with
// no content and no conclusion — so the model read the same file again, and again.
//
// This only fires for models that emit tool syntax as TEXT; models using native tool_calls take
// a different path that persists its own summary. That asymmetry is why context appeared to
// work on one model and not another.
test("_agentFollowUp persists its reply to real session memory, not a throwaway copy", () => {
  const fn = extractFn("_agentFollowUp");

  assert.match(fn, /sess\?\.memory\?\.push\(\{ role: "assistant", content: acc \}\)/,
    "the reply must be pushed onto the session's real memory");
  // Strip // comments first: the fix's own comment quotes the old broken call, and a naive
  // negative match would hit the prose describing the bug rather than the bug.
  const code = fn.replace(/^\s*\/\/.*$/gm, "");
  assert.ok(!/_hist\.push\(/.test(code),
    "pushing onto the assemble() copy is a no-op — it must not come back");

  // _hist itself is still legitimate: it is the read-only snapshot spread into the request.
  assert.match(fn, /\.\.\._hist,/, "_hist is still the request-building snapshot");

  // assemble() really does hand back a new array — the premise the bug rested on.
  const mem = readFileSync(join(HERE, "../src/conversation-memory.js"), "utf8");
  const slice = mem.slice(mem.indexOf("assembledSlice(from"), mem.indexOf("assembledSlice(from") + 1400);
  assert.match(slice, /const result = \[\]/, "assembledSlice builds a fresh array");
  assert.match(slice, /return result;/, "…and returns it, so callers cannot mutate memory through it");
});

// ---- folding a read must also invalidate its duplicate-read stubs ----
//
// When the transcript passes the soft budget, Tier 2 compresses old tool results and marks
// read messages contextAvailable:false. But the "authorized" / "hard_blocked" dedup stubs are
// only ~80-130 chars, so the `c.length > cap + 80` (480) test never matches them — they
// survive untouched, still carrying whole-file coverage evidence.
//
// _syncRunReadCoverageFromMessages credits those stubs as real coverage. So once the 55k
// content message is folded, the stub alone re-registers full coverage, and the next read_file
// is answered with the stub's own text — "完整原文就在上文…不需要重读" — for bytes that are
// gone. The model declines to re-read and reasons about nothing. This is keyed to the selected
// model's context window, so it triggers earlier on smaller models.
test("Tier-2 fold invalidates duplicate-read stubs for the same file", () => {
  const fn = extractFn("_trimMessagesIfHuge");

  assert.match(fn, /_foldedSigs/, "the fold must record which file signatures it folded");
  assert.match(fn, /meta\.resultKind !== "content"/,
    "stubs (authorized / hard_blocked) must be targeted, not just content messages");
  assert.match(fn, /_foldedSigs\.has\(meta\.signature\)/,
    "only stubs whose underlying content was folded may be invalidated");

  // Ordering: signatures must be collected before the stub sweep can use them.
  const collect = fn.indexOf("_foldedSigs.add(meta.signature)");
  const sweep = fn.indexOf("_foldedSigs.has(meta.signature)");
  assert.ok(collect > -1 && sweep > -1 && collect < sweep,
    "signatures are collected during the fold, then applied to stubs afterwards");

  // The coverage resync must still treat stubs as coverage-bearing — that is WHY they have to
  // be invalidated here rather than filtered there (filtering there reintroduces the
  // read/write-gate deadlock the surrounding comments guard against).
  assert.match(SRC, /resultKind === "hard_blocked" \|\| meta\?\.resultKind === "authorized"/,
    "stubs still count as coverage in the resync; the fix belongs at fold time");
});

// ---- context-window selector: honest clamping and membership gating ----
//
// The model card renders native + all three michael-compression tiers as buttons. A stored
// choice may NARROW the window (a cost dial) but must never budget past what native-or-
// membership actually delivers — a fictional window dies upstream as context-length 400s.
test("context-window choice clamps to what is actually deliverable", () => {
  const mkEff = (store, user, compress) => load("_effectiveContextLimit", {
    _modelContextLimit: () => 200_000,
    _michaelUser: user,
    _gatewayHandlesCompression: () => compress,
    _ctxChoiceFor: () => store,
  });
  const tier5m = { michael_compression: { tier: "5m", max_input_tokens: 5_000_000 } };

  assert.equal(mkEff(0, tier5m, true)("m"), 5_000_000, "no choice → membership default");
  assert.equal(mkEff(2_000_000, tier5m, true)("m"), 2_000_000, "choice narrows within membership");
  assert.equal(mkEff(200_000, tier5m, true)("m"), 200_000, "native is always selectable");
  assert.equal(mkEff(5_000_000, null, true)("m"), 200_000,
    "membership gone → stored 5M silently falls back to native, never a fictional window");
  assert.equal(mkEff(2_000_000, tier5m, false)("m"), 200_000,
    "gateway compression off → tiers are not deliverable, clamp to native");

  const mkOpts = (user, compress) => load("_ctxChoiceOptions", {
    _modelContextLimit: () => 200_000,
    _michaelUser: user,
    _gatewayHandlesCompression: () => compress,
    _tokenShort: (n) => n >= 1_000_000 ? (n / 1_000_000) + "m" : (n / 1000) + "k",
    _MC_TIER_OPTIONS: [["1M", 1_000_000], ["2M", 2_000_000], ["5M", 5_000_000]],
  });
  const opts1m = mkOpts({ michael_compression: { tier: "1m", max_input_tokens: 1_000_000 } }, true)("m");
  assert.equal(opts1m.length, 4, "native + ALL three tiers are displayed regardless of membership");
  assert.equal(opts1m[0].native, true);
  assert.equal(opts1m[1].locked, false, "1M tier selectable on a 1M membership");
  assert.equal(opts1m[2].locked, true, "2M tier locked above membership");
  assert.equal(opts1m[3].locked, true, "5M tier locked above membership");
  assert.match(opts1m[2].lockHint, /2M/, "locked tier explains what unlocks it");
});

// ---- free allowance is denominated in 点, not dollars ----
//
// The operator prices in 点: ¥0.5 = 10 点, so 1 点 = ¥0.05 and the ¥2 daily allowance is
// exactly 40 点. The first cut stored raw provider cents and rendered them through the
// credit-dollar denominator (663 raw cents = $1.00), which showed a ¥2 allowance as "$3.02" —
// a real number in the wrong currency. Points are the unit; render them as such.
test("free allowance renders in 点 and never through the dollar denominator", () => {
  const fn = load("_freePointsMetric");
  const seen = [];
  const metric = (label, value, pct, sub) => { seen.push({ label, value, pct, sub }); return "ROW"; };
  const usd = () => { throw new Error("free points must NOT go through the usd() denominator"); };

  const out = fn(metric, usd, { free_points: 40, free_points_daily: 40 });
  assert.equal(out, "ROW");
  assert.equal(seen[0].label, "免费额度");
  assert.equal(seen[0].value, "40 点", "a full pool reads cleanly, no trailing zeros");
  assert.equal(seen[0].pct, 100);
  assert.match(seen[0].sub, /40 点/);
  assert.match(seen[0].sub, /¥2\.00/, "¥0.5 = 10 点 ⇒ 40 点 is ¥2.00");

  // partially spent
  seen.length = 0;
  fn(metric, usd, { free_points: 10, free_points_daily: 40 });
  assert.equal(seen[0].value, "10 点");
  assert.equal(seen[0].pct, 25);

  // Sub-点 balances must render, or a cheap model would appear to cost nothing all day.
  seen.length = 0;
  fn(metric, usd, { free_points: 39.94, free_points_daily: 40 });
  assert.equal(seen[0].value, "39.94 点", "fractional balances are visible");

  // exhausted → tells the user paid models still work
  seen.length = 0;
  fn(metric, usd, { free_points: 0, free_points_daily: 40 });
  assert.equal(seen[0].value, "0 点");
  assert.match(seen[0].sub, /付费模型不受影响/);

  // absent field (older gateway) → render nothing rather than a misleading zero
  assert.equal(fn(metric, usd, {}), "");
  assert.equal(fn(metric, usd, { free_points: null }), "");
});

// ---- verification credit must decay with the artifact it certified ----
//
// The pre-delivery gate asked "has anything ever been verified this run?" using three
// credentials that are monotonic for the life of the run. So `npm test` after edit #1
// certified edits #2..#12 too — including the one that broke the build — and the run still
// reported success with "验证：已通过真实命令/检查。" attached. That is the modal shape of a
// hard task (verify early, keep refactoring), which made it a ceiling rather than an edge case.
//
// The fix consults the edit-count stamp already written onto every evidence record
// (`implementationVersion`) and expires the credential in the mutation handlers, alongside the
// sibling credentials that were ALREADY being reset there.
test("verification credit expires when files change under it", () => {
  const loop = extractFn("_runAgenticLoop");

  // freshness, not existence
  assert.match(loop, /_hasVerifyEvidence = _verifiedAtImplOps >= _implOps/,
    "the gate must compare against the current edit count, not >= 0");
  assert.ok(!/_hasVerifyEvidence = verificationPassed \|\| didVerify \|\| _verifiedAtImplOps >= 0/.test(loop),
    "the monotonic form must not come back");

  // The stamp that was written and never read is now read. The staleness check moved
  // out of the loop into the named _evidenceCertifies (so it can be tested as a pure
  // predicate rather than by matching source text); the loop must still delegate to it,
  // and must still write the stamp when it records evidence.
  assert.match(loop, /_executionEvidence\.some\(\(e\) => _evidenceCertifies\(e, _implOps\)\)/,
    "the gate must delegate per-record certification to _evidenceCertifies");
  assert.match(loop, /implementationVersion: _implOps/, "…and still written when evidence is recorded");
  assert.match(SRC, /function _evidenceCertifies\(e, implOps\)[\s\S]*?implementationVersion\) < implOps/,
    "stale evidence records must still be rejected by their edit stamp");

  // both mutation handlers expire it, matching their sibling resets
  assert.equal((loop.match(/_verifiedAtImplOps = -1;/g) || []).length, 2,
    "both the file-mutation and worker-mutation handlers must expire verification credit");
  assert.equal((loop.match(/verificationPassed = false;/g) || []).length, 2,
    "…and clear the boolean alongside it");

  // didVerify must NOT be cleared: it means "a check was attempted", not "state is proven"
  assert.ok(!/didVerify = false;/.test(loop),
    "didVerify tracks attempts, not proof — clearing it would re-trigger verifier-unavailable cards");

  // the stale comment claiming the gate was removed must be gone
  assert.ok(!/验证门已拆/.test(loop), "the comment justifying the sticky credential is no longer true");
});

// ---- R2: the plan must be visible to the reasoner, not just the UI ----
test("the scratchpad renders the whole plan, not a completed-tally", () => {
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /任务计划 \$\{_doneN\}\/\$\{_ps\.length\}/,
    "the pad must show progress over the full plan");
  assert.match(loop, /status === "in_progress" \? "\[→\]"/, "in-progress steps must be marked");
  assert.ok(!/_pad\.done/.test(loop),
    "the completed-only tally is retired — it hid which step was current");
  assert.match(loop, /run\._planSteps.*filter\(\(x\) => x && x\.status !== "cancelled"\)/,
    "sourced from the live plan, and cancelled steps excluded");
});

// ---- R3: folding source through an error-log extractor destroys what an edit needs ----
test("folded reads keep a line-anchored skeleton", () => {
  // extractFn only pulls functions; _SKEL_RE is a const regex, so read it from source.
  const src = readFileSync(join(HERE, "../src/main.js"), "utf8");
  const reSrc = src.match(/const _SKEL_RE = (\/.*\/);/)[1];
  const fn = new Function("_SKEL_RE", extractFn("_codeSkeleton") + "\n;return _codeSkeleton;")(eval(reSrc));

  const body = ["import x from 'y';", "export function a() {", "  const inner = 1;", "class B {}"].join("\n");
  const out = fn(body, 800, 500);
  assert.match(out, /^501: export function a\(\) \{$/m, "line anchors must be TRUE file lines");
  assert.match(out, /^503: class B \{\}$/m);
  assert.ok(!/inner/.test(out), "bodies are dropped; only definitions are kept");
  assert.equal(fn("", 800, 1), "", "empty body yields no skeleton");

  const loop = readFileSync(join(HERE, "../src/main.js"), "utf8");
  assert.match(loop, /skeleton: _codeSkeleton\(_safeBody, 800, shownFrom\)/,
    "computed where _safeBody and shownFrom are correct — NOT from the prefixed message body");
  assert.match(loop, /行号真实——用 read_file offset\/limit/,
    "the fold must tell the model a ranged re-read is enough");
});

// ---- R5: the critic must judge the product, not only the process ----
test("the wrap-up critic receives the actual diff", () => {
  const critic = extractFn("_wrapUpCritic");
  assert.match(critic, /changeDigest = ""/, "critic accepts a change digest");
  assert.match(critic, /本轮实际改动（真实 diff）/, "…and renders it in the user block");
  assert.match(critic, /先读【本轮实际改动】里的真实 diff/,
    "…and is instructed to judge the change itself, not just whether commands ran");
  assert.match(critic, /即使命令全绿/, "green commands must not by themselves mean done");

  const hunk = new Function(extractFn("_changedHunk") + "\n;return _changedHunk;")();
  assert.equal(hunk("same", "same"), "", "identical content produces no hunk");
  const d = hunk("a\nb\nc", "a\nB\nc");
  assert.match(d, /^- b$/m); assert.match(d, /^\+ B$/m);
  assert.match(d, /^@@ /m, "hunks carry a position header");
  // bounded: a huge change must not blow the critic's budget
  const big = hunk("x\n".repeat(500), "y\n".repeat(500), 3, 40);
  assert.ok(big.split("\n").length <= 41, "hunks are capped");
});

// ---- R4: reasoning depth must track live difficulty, and the meter must not lie ----
test("reasoning depth is re-derived each iteration from live run state", () => {
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /failStreak = lastTurnHadFailure \? failStreak \+ 1 : 0;/,
    "consecutive failures are tracked, not just the last turn");
  assert.match(loop, /const _cx = isComplexTask \|\| failStreak >= 2 \|\| quietTurns >= 2/,
    "difficulty discovered at runtime must raise depth");
  assert.match(loop, /_applyThinkingToConfig\(_rawConfig, \{ agentTurn: true, isComplexTask: _cx \}\)/,
    "re-derived from _rawConfig — mutating config in place would leave stale family keys");
  // the meter was written once, pre-loop, from the un-demoted config
  assert.match(loop, /_activeThinkEffort = config\.thinkingEffort/,
    "the meter must be written inside the loop so it reports what is actually on the wire");
});

// ---- two built-but-never-connected reasoning features ----
//
// `_diagnosticBlock` had only `= ""` assignments, so the BLOCKING_NEW_DIAGNOSTICS gate — with
// its staleness expiry and `continue` — was unreachable. `_prevVerifyErrs`/`_noProgressVerify`
// (declared "re-verify after new edits; stop once errors stop dropping") were never written,
// leaving `hadDiagnostics` permanently false in the run summary.
//
// The convergence bound matters more now that verification credit expires on every edit:
// without it, "verify again" could thrash on a project whose errors are not improving.
test("the diagnostic block and auto-verify convergence loop are actually wired", () => {
  const loop = extractFn("_runAgenticLoop");

  // the block is now populated from real markers, not just cleared
  assert.match(loop, /run\._diagnosticBlock = formatDiagnosticsForAgent\(_errMarkers, root/,
    "the blocking gate must receive real diagnostics");
  assert.ok(/getProblemMarkers\(\)\.filter\(\(m\) => m\.severity === SEV\.Error\)/.test(loop),
    "errors (not warnings) drive the gate");

  // convergence: progress resets, stagnation counts, two rounds stop pushing
  assert.match(loop, /_noProgressVerify\+\+/, "stagnation must be counted");
  assert.match(loop, /_noProgressVerify = 0; \/\/ errors are dropping/, "progress must reset the counter");
  assert.match(loop, /_noProgressVerify < 2/, "…and two stalled rounds must stop the blocking");
  assert.match(loop, /_prevVerifyErrs = _errNow;/, "the error count must be carried forward");

  // a clean tree must clear the block, or a fixed error would keep blocking forever
  assert.match(loop, /_errNow === 0/, "zero errors clears the block");

  // the summary field that was permanently false now has a source
  assert.match(loop, /hadDiagnostics: !!_prevVerifyErrs/, "run summary reads the tracked count");
});

// ---- michael-design must trigger on real UI work, not just website-shaped surfaces ----
//
// MICHAEL_DESIGN_TRIGGER_DIAGNOSIS.md: the design knowledge only loaded when deliverySurface
// was ui_component/website/web_app/desktop. A full-stack job reports `mixed`, so "build the
// front-end for this client" silently ran WITHOUT the design system — which is exactly when
// it is needed. Widening by surface alone would over-trigger on backend-heavy `mixed` work, so
// the verdict's own roleNeeds decides: a pure backend task never lists frontend/design.
test("design knowledge triggers on mixed-surface work that needs frontend or design", () => {
  const src = readFileSync(join(HERE, "../src/main.js"), "utf8");
  const m = src.match(/const uiSurface = \[[\s\S]*?\n\s*\|\| \(\(deliverySurface === "mixed"[\s\S]*?\)\);/);
  assert.ok(m, "the widened uiSurface predicate must exist");
  const fn = new Function("deliverySurface", "engineering",
    "const _roles = Array.isArray(engineering?.roleNeeds) ? engineering.roleNeeds : [];\n"
    + m[0] + "\nreturn uiSurface;");

  // classic UI surfaces still trigger
  for (const s of ["ui_component", "website", "web_app", "desktop"]) {
    assert.equal(fn(s, {}), true, `${s} must trigger`);
  }
  // full-stack work that includes front-end now triggers
  assert.equal(fn("mixed", { roleNeeds: ["backend", "frontend"] }), true,
    "a mixed task needing frontend is UI work");
  assert.equal(fn("mixed", { roleNeeds: ["design"] }), true);
  // …but backend-only mixed work does NOT — this is the over-trigger the diagnosis warned about
  assert.equal(fn("mixed", { roleNeeds: ["backend", "database"] }), false,
    "backend-heavy mixed work must not pull in the design system");
  assert.equal(fn("backend", { roleNeeds: ["frontend"] }), false,
    "an explicit backend surface stays out regardless of roles");
  assert.equal(fn("mixed", {}), false, "no roles → no false trigger");
});

// ---- the streaming freeze on long replies ----
//
// Forensics, not guesswork: /tmp/michael-ide-perf.log recorded stalls of 7.1s, 7.7s, 7.3s,
// 11.3s and one of 149s, every one reporting "no phase markers inside the freeze window".
// Every instrumented phase (renderMarkdownStream, _cleanAgentText, highlightCode,
// persistChatHistory) was therefore innocent — the hot code was simply unmarked.
//
// _parseStreamSegments re-split and regex-scanned the WHOLE accumulated reply, and the
// streaming renderer called it on every delta: cost grows with length². It carried no perf
// marker, which is exactly why the sentinel was blind to it.
test("the per-delta segment parse is marked, memoised and throttled", () => {
  const fn = extractFn("_parseStreamSegments");
  assert.match(fn, /_perfPhase\(`_parseStreamSegments len=/,
    "must be instrumented, or the sentinel stays blind to it");
  assert.match(fn, /if \(text === _parseStreamSegments\._in\) return _parseStreamSegments\._out;/,
    "identical input must not be re-parsed");
  assert.match(fn, /_parseStreamSegments\._out = segs;/, "…and the result must be cached");

  assert.match(SRC, /const _due = !renderStream\._at \|\| \(_nowMs - renderStream\._at\) >= 150;/,
    "the per-delta call must be throttled — the memo always misses on a growing accumulator");
  assert.match(SRC, /segs = renderStream\._segs;/,
    "between parses the last segment list must be reused, not recomputed");
});

// ---------------------------------------------------------------------------
// Read-before-write gate: a whole-file write is not a bypass.
//
// write_file to an existing file used to be exempt from the read gate whenever the
// content was a non-empty string ("completeWholeWrite"), on the theory that a full
// diff plus Undo made it safe. Undo-ability is not correctness — content written from
// the model's prior drops whatever it never read. Worse, the recovery text for a
// blocked edit_file told the model that "only edit_file / multi_edit need read_file",
// so the gate actively routed blind rewrites through write_file.
// ---------------------------------------------------------------------------
test("_writeGateBypass: whole-file write to an existing file is NOT a bypass", () => {
  const gate = load("_writeGateBypass");
  // The exact shape the old completeWholeWrite disjunct waved through.
  assert.equal(
    gate({ type: "write", content: "export const x = 1;\n" }, { redactedRead: false }),
    false,
    "a complete, non-empty whole-file write must still require read evidence",
  );
  assert.equal(gate({ type: "write", content: "   " }, {}), false);
  assert.equal(gate({ type: "write", content: "" }, {}), false);
});

test("_writeGateBypass: redacted write-back keeps its exemption", () => {
  const gate = load("_writeGateBypass");
  // The model read a MASKED current version, so it does hold current-version evidence.
  assert.equal(
    gate({ type: "write", content: "key = [REDACTED_API_KEY]\n" }, { redactedRead: true }),
    true,
  );
  assert.equal(gate({ type: "write", content: "key = REDACTED\n" }, { redactedRead: true }), true);
  // Redacted read, but the write carries no placeholder → not a write-back, no exemption.
  assert.equal(
    gate({ type: "write", content: "key = hunter2\n" }, { redactedRead: true }),
    false,
    "a redacted read does not license writing content with no placeholders",
  );
  // Placeholder present but nothing was redacted → the flag is what licenses this.
  assert.equal(
    gate({ type: "write", content: "key = [REDACTED]\n" }, { redactedRead: false }),
    false,
  );
});

test("_writeGateBypass: precise local edit anchors remain a bypass", () => {
  const gate = load("_writeGateBypass");
  assert.equal(gate({ type: "edit" }, { preciseLocalEdit: true }), true);
  assert.equal(gate({ type: "edit" }, { preciseLocalEdit: false }), false);
  // multi_edit gets no bypass THROUGH THIS FUNCTION. Note it is not un-bypassable overall: the
  // multiedit branch checks _localEditHasPreciseAnchors inline at its own gate site. Both paths
  // now require a unique anchor per edit, so neither can stand in for reading an unread file.
  assert.equal(gate({ type: "multiedit" }, { preciseLocalEdit: true }), false);
});

test("_writeGateBypass: tolerates malformed calls without throwing", () => {
  const gate = load("_writeGateBypass");
  assert.equal(gate(null), false);
  assert.equal(gate(undefined), false);
  assert.equal(gate("write"), false);
  assert.equal(gate({ type: "write" }), false, "missing content is not a bypass");
  assert.equal(gate({ type: "write", content: 42 }, { redactedRead: true }), false);
});

// ---------------------------------------------------------------------------
// A failing build is not verification.
//
// _hasVerifyEvidence had three routes to true (an explicit `verification` stamp,
// _looksLikeVerificationCommand, and _runtimeCommandKinds) and all three matched on the
// COMMAND'S SHAPE with no reference to its exit status. `npm run build` exiting non-zero
// therefore certified the very code it had just proven broken. Exit status now rides on
// the evidence record as `ok`, and the predicate rejects `ok === false` before any
// shape test runs.
// ---------------------------------------------------------------------------
const _verifyEvidenceAccepts = (evidence, implOps = 1) => {
  const certifies = load("_evidenceCertifies", {
    _looksLikeVerificationCommand: (c) =>
      /\b(npm|pnpm|yarn|cargo|go|make)\b.*\b(build|test|check)\b/.test(c),
    _runtimeCommandKinds: (c) => (/\b(build|test|run|package)\b/.test(c) ? ["build"] : []),
  });
  return evidence.some((e) => certifies(e, implOps));
};

test("verify gate: certification requires a declaration or the IDE's own stamp", () => {
  const certifies = load("_evidenceCertifies");
  // The IDE stamps `verification` when a DECLARED verification exited 0.
  assert.equal(certifies({ command: "npm run build", implementationVersion: 2, ok: true, verification: true }, 2), true);
  // A record carrying the model's declaration certifies directly.
  assert.equal(certifies({ command: "python check.py", implementationVersion: 2, ok: true, purpose: "verify" }, 2), true);
  // Undeclared and unstamped certifies NOTHING — silence is not evidence. This is the
  // deliberate break from the old text floor, which guessed from the command string.
  assert.equal(certifies({ command: "npm run build", implementationVersion: 2, ok: true }, 2), false);
  // Red never certifies, however it is declared or stamped.
  assert.equal(certifies({ command: "npm run build", implementationVersion: 2, ok: false, verification: true }, 2), false);
  assert.equal(certifies({ command: "python check.py", implementationVersion: 2, ok: true, exitCode: 1, purpose: "verify" }, 2), false);
  // No text classifier may be consulted here any more.
  assert.doesNotMatch(extractFn("_evidenceCertifies"), /_looksLikeVerificationCommand|_runtimeCommandKinds/,
    "certification must not read command text");
  // The IDE only sets that stamp for a DECLARED verification that exited 0.
  assert.match(SRC, /if \(\(call\.type === "cmd" \|\| call\.type === "termtask"\)\s*\n\s*&& call\.purpose === "verify"\s*\n\s*&& _toolExecutionSucceeded\(call, result\)\) \{/,
    "the verification stamp requires the declaration plus a green exit");
});

test("verify gate: stale evidence still loses to a newer edit", () => {
  // The implementationVersion rule must keep working alongside the ok rule.
  assert.equal(
    _verifyEvidenceAccepts([{ command: "npm run build", implementationVersion: 1, ok: true }], 5),
    false,
  );
});

// ---------------------------------------------------------------------------
// Shell-written code carries the same verification obligation as tool-written code.
//
// _mutatedFiles is populated only by the structured write/edit tools, and _mutatedCode
// derived solely from it — so `sed -i` on a .ts file, a heredoc, or `npm create vite`
// (a whole project) bumped _implOps while leaving _mutatedCode false, and
// _codeDeliveredUnverified could never fire for exactly the runs that write the most code.
// ---------------------------------------------------------------------------
test("_commandWroteCode: answers from watcher-observed paths, not command text", () => {
  const wroteCode = load("_commandWroteCode", {
    _toolExecutionSucceeded: (_c, r) => (r && r.code) === 0,
    _CODE_FILE_RE: /\.(?:js|jsx|ts|tsx|py|rs|go)$/i,
  });
  const ok = { code: 0 };
  // A generator whose NAME says nothing — invisible to any classifier, visible in fact.
  assert.equal(wroteCode({ type: "cmd", command: "python gen.py", purpose: "mutate" },
    { ...ok, _fsPaths: ["src/App.tsx"] }), true);
  // Same command, only non-code output → no code obligation.
  assert.equal(wroteCode({ type: "cmd", command: "python gen.py", purpose: "mutate" },
    { ...ok, _fsPaths: ["out/report.txt"] }), false);
  // Even undeclared, observed code writes count.
  assert.equal(wroteCode({ type: "cmd", command: "make all" }, { ...ok, _fsPaths: ["src/x.rs"] }), true);
  // A declared scaffold with no watcher report still counts (the watcher may miss a
  // burst); declaration is the fallback, never the overrule.
  assert.equal(wroteCode({ type: "cmd", command: "npm create vite", purpose: "scaffold" }, ok), true);
  assert.equal(wroteCode({ type: "cmd", command: "ls", purpose: "explore" }, ok), false);
  assert.equal(wroteCode({ type: "cmd", command: "npm create vite", purpose: "scaffold" }, { code: 1 }), false,
    "a failed command wrote nothing worth verifying");
  assert.doesNotMatch(extractFn("_commandWroteCode"), /_looksLikeScaffoldCommand|_looksLikeShellFileRewrite/);
});

test("_toolMutatesWorkspace: an observed fs delta outranks any declaration", () => {
  const mutates = load("_toolMutatesWorkspace", {
    _WORKSPACE_MUTATING_TYPES: new Set(["write"]),
    _mcpMutationHint: () => false,
  });
  // Fact wins even when the model declared the command read-only.
  assert.equal(mutates({ type: "cmd", command: "./tool.sh", purpose: "explore" }, { _fsDelta: true }), true,
    "the watcher cannot be talked out of by a wrong declaration");
  // Declaration covers what the watcher missed.
  assert.equal(mutates({ type: "cmd", command: "./tool.sh", purpose: "mutate" }, { _fsDelta: false }), true);
  // Neither → not a mutation.
  assert.equal(mutates({ type: "cmd", command: "ls -la", purpose: "explore" }, { _fsDelta: false }), false);
  assert.equal(mutates({ type: "termtask", command: "npm run dev", purpose: "run" }, {}), false);
  assert.doesNotMatch(extractFn("_toolMutatesWorkspace"), /_looksLikeWorkspaceMutationCommand|_looksLikeScaffoldCommand/);
});

test("agent loop: shell-written code feeds _mutatedCode and the index stays alive", () => {
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /_commandWroteCode\(it\.call, it\.rawResult\)/,
    "the mutation handler must record shell-written code");
  assert.match(loop, /run\._codeWrittenByCommand === true/,
    "_mutatedCode must consider code written by shell commands");
  // Index liveness: agent writes refresh the symbol index like human saves do,
  // and BM25 invalidation schedules a rebuild instead of blinding retrieval for the session.
  assert.match(extractFn("_executeToolStepInner"), /refreshSymbolIndexFor\(fp\)/);
  assert.match(extractFn("handleFsChanges"), /buildBM25Index\(_bm25Index\.root\)/,
    "invalidating the BM25 index must schedule its rebuild");
});

// ---------------------------------------------------------------------------
// Sub-agents get a tool-discovery escape hatch, filtered by their own sandbox.
//
// A child's toolset was frozen at dispatch for its whole 12–18-turn life; guessing a
// tool name — the moment it signals which capability it needs — earned a static
// [BLOCKED] and a burned turn. search_tools now answers that signal: same-sandbox tools
// are admitted into the child's payload, out-of-sandbox hits are named so the child's
// report can route the need to the parent. MCP stays out-of-sandbox by design (workers
// are scope-bounded; MCP mutations cannot be scope-checked), so it lands in `outside`.
// ---------------------------------------------------------------------------
test("_subAgentAdmitTools: admits same-capability tools, names out-of-sandbox ones", () => {
  const mkSchema = (n) => ({ type: "function", function: { name: n, parameters: {} } });
  const registry = new Map([
    ["semantic_search", mkSchema("semantic_search")],
    ["run_terminal", mkSchema("run_terminal")],
    ["mcp__db__query", mkSchema("mcp__db__query")],
  ]);
  const admit = load("_subAgentAdmitTools", {
    _STRICT_MUTATING_TOOL_NAMES: new Set(["deploy_site", "git_commit", "git_push", "run_cmd"]),
    _searchToolsExactQuery: () => false,
    _searchToolsLookup: () => [],
    _searchToolsFuzzyMatch: (_q, reg) =>
      [...reg.values()].map((schema) => ({ schema, alreadyLoaded: false })),
  });
  const typeOf = { semantic_search: "semsearch", run_terminal: "termtask", mcp__db__query: "mcp" };
  const res = admit("search code semantically", {
    registry,
    loaded: new Set(),
    execTypes: ["read", "semsearch"],           // a read-only child
    mapCall: (n) => ({ type: typeOf[n] || "" }),
  });
  assert.deepEqual(res.admitted.map((s) => s.function.name), ["semantic_search"]);
  assert.deepEqual(res.outside.sort(), ["mcp__db__query", "run_terminal"]);
});

test("_subAgentAdmitTools: fails closed on matcher errors and unmappable names", () => {
  const admit = load("_subAgentAdmitTools", {
    _STRICT_MUTATING_TOOL_NAMES: new Set(["deploy_site"]),
    _searchToolsExactQuery: () => { throw new Error("registry exploded"); },
    _searchToolsLookup: () => [],
    _searchToolsFuzzyMatch: () => [],
  });
  const res = admit("anything", { registry: new Map(), loaded: new Set(), execTypes: ["read"], mapCall: () => ({}) });
  assert.deepEqual(res, { admitted: [], outside: [] }, "a matcher error must yield empty, not throw");

  const admit2 = load("_subAgentAdmitTools", {
    _STRICT_MUTATING_TOOL_NAMES: new Set(["deploy_site"]),
    _searchToolsExactQuery: () => false,
    _searchToolsLookup: () => [],
    _searchToolsFuzzyMatch: () => [
      { schema: { type: "function", function: { name: "mystery_tool", parameters: {} } }, alreadyLoaded: false },
    ],
  });
  const res2 = admit2("q", { registry: new Map(), loaded: new Set(), execTypes: ["read"], mapCall: () => { throw new Error("no mapping"); } });
  assert.deepEqual(res2.admitted, [], "unmappable tools must not be admitted");
  assert.deepEqual(res2.outside, ["mystery_tool"], "…but must still be reported");
});

test("sub-agent loop: search_tools is answered before the allowlist, via the payload window", () => {
  const sub = extractFn("_runSubAgent");
  assert.match(sub, /_SEARCH_TOOLS_SCHEMA,\s*\n\s*\];/,
    "children must be offered the discovery entry point");
  const searchIdx = sub.indexOf('call.type === "search_tools"');
  const allowIdx = sub.indexOf("!_execTypes.includes(call.type)");
  assert.ok(searchIdx >= 0 && allowIdx > searchIdx,
    "discovery must be handled before the allowlist rejection");
  // Admission goes through the same capped window as the main loop — a raw
  // toolSchemas.push would bypass the byte/count limits (and is banned globally by the
  // payload-window test above). The window splices the SAME array the next turn reads.
  assert.match(sub, /_applyToolPayloadWindow\(toolSchemas, _found\.admitted, _childCoreNames\)/);
  assert.doesNotMatch(sub, /toolSchemas\.push/);
});

// ---------------------------------------------------------------------------
// Fixes from the adversarial review of the gate work (2026-08-02).
// Each of these was a CONFIRMED defect in the first version of the gates.
// ---------------------------------------------------------------------------
test("review: strict-mutating tools are never admitted into a child by type", () => {
  // deploy_site maps to type "cmd" — which every child has — but publishes the
  // workspace to a public domain. Type alone must not admit it.
  const mkSchema = (n) => ({ type: "function", function: { name: n, parameters: {} } });
  const admit = load("_subAgentAdmitTools", {
    _STRICT_MUTATING_TOOL_NAMES: new Set(["deploy_site", "git_commit", "git_push"]),
    _searchToolsExactQuery: () => false,
    _searchToolsLookup: () => [],
    _searchToolsFuzzyMatch: (_q, reg) =>
      [...reg.values()].map((schema) => ({ schema, alreadyLoaded: false })),
  });
  const registry = new Map([
    ["deploy_site", mkSchema("deploy_site")],
    ["git_commit", mkSchema("git_commit")],
    ["mcp__db__query", mkSchema("mcp__db__query")],
  ]);
  const typeOf = { deploy_site: "cmd", git_commit: "git", mcp__db__query: "mcp" };
  const res = admit("deploy my site", {
    registry, loaded: new Set(),
    execTypes: ["read", "cmd", "git"],          // worker sandbox: type-level would admit all but mcp
    mapCall: (n) => ({ type: typeOf[n] || "" }),
  });
  assert.deepEqual(res.admitted, [], "no strict-mutating tool may enter via discovery");
  assert.deepEqual(res.outside.sort(), ["deploy_site", "git_commit", "mcp__db__query"],
    "…but each must be named so the report can route it to the parent");
});

test("review: evidence with a non-zero exitCode never certifies, even when ok=true", () => {
  // read_terminal on an exited terminal SUCCEEDS as a read (ok=true) while carrying the
  // real command and exitCode:1 — looking at a failure must not mint green evidence.
  const certifies = load("_evidenceCertifies");
  assert.equal(certifies({ command: "npm run build", implementationVersion: 3, ok: true, exitCode: 1, purpose: "verify" }, 3), false);
  assert.equal(certifies({ command: "npm run build", implementationVersion: 3, ok: true, exitCode: 0, purpose: "verify" }, 3), true);
  // null/undefined exitCode (still running, no code reported) keeps its old meaning.
  assert.equal(certifies({ command: "npm run build", implementationVersion: 3, ok: true, exitCode: null, purpose: "verify" }, 3), true);
});

test("review: a declared verification never arms the semantic-review gate", () => {
  // Red or green, a declared verification has an exit-status contract: fix it, never
  // "have a paid critic interpret the output". Application runs still need review.
  const needs = load("_runtimeNeedsSemanticReview", {
    _executionEvidenceFromTool: () => ({ command: "npm run build", exitCode: 1 }),
  });
  assert.equal(needs({ type: "cmd", command: "npm run build", purpose: "verify" }, { code: 1 }), false);
  assert.equal(needs({ type: "cmd", command: "python app.py", purpose: "run" }, { code: 0 }), true,
    "application runs still require semantic postcondition review");
  assert.doesNotMatch(extractFn("_runtimeNeedsSemanticReview"), /_looksLikeVerificationCommand/);
});

test("review: files whose read coverage is mechanically impossible bypass the write gate", () => {
  const impossible = load("_readCoverageImpossible", { _READ_SLICE_CHAR_CAP: 55000 });
  const gate = load("_writeGateBypass");
  const giant = "x".repeat(60001);                       // one line > the 55k slice cap
  assert.equal(impossible(giant), true);
  assert.equal(impossible("short\n".repeat(1000)), false);
  assert.equal(impossible(`head\n${giant}\ntail`), true, "any single over-cap line suffices");
  assert.equal(
    gate({ type: "write", content: "minified" }, { coverageImpossible: true }), true,
    "the gate must not demand evidence the reader cannot produce");
  assert.equal(
    gate({ type: "write", content: "minified" }, { coverageImpossible: false }), false);
});

test("review: eager writes evaluate the read gate at the in-flight turn", () => {
  const hasRead = load("_runHasCurrentRead", {
    _normRel: (p) => p,
    _contentSignature: () => "sig",
  });
  const run = {
    _toolBatch: 2,
    ctx: { filesRead: new Set(["a.ts"]) },
    _readCoverage: new Map([["a.ts", { signature: "sig", completedBatch: 2 }]]),
  };
  // Batch path: a read completed THIS batch does not authorize (same-turn write).
  assert.equal(hasRead(run, "", "content", "a.ts"), false);
  // Eager path: the bias reflects that execution belongs to turn N+1.
  run._eagerTurnBias = 1;
  assert.equal(hasRead(run, "", "content", "a.ts"), true,
    "a file read in the immediately preceding turn must authorize its eager rewrite");
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /run\._eagerTurnBias = 1;/, "the eager hook must set the bias");
  assert.match(loop, /run\._eagerTurnBias = 0;\s*\n\s*run\._toolBatch = \(run\._toolBatch \|\| 0\) \+ 1;/,
    "the real increment must clear it");
});

test("review: install-type commands mutate but carry no code obligation by themselves", () => {
  const wroteCode = load("_commandWroteCode", {
    _toolExecutionSucceeded: () => true,
    _CODE_FILE_RE: /\.(?:ts|js)$/i,
  });
  // `npm init -y` writes package.json only: a mutation, not code. With no observed code
  // path and no scaffold declaration, no build obligation is armed.
  assert.equal(wroteCode({ type: "cmd", command: "npm init -y", purpose: "install" },
    { code: 0, _fsPaths: ["package.json"] }), false);
  // A real scaffold that lands code does arm it.
  assert.equal(wroteCode({ type: "cmd", command: "npm create vite@latest app", purpose: "scaffold" },
    { code: 0, _fsPaths: ["src/main.ts"] }), true);
});

test("L0 strip keeps client-side tuning while still dropping the bundled prompt", () => {
  const preserve = load("_l0MessagesWithSkills");
  const out = preserve([
    { role: "system", content: "private bundled prompt" },
    { role: "user", content: "build it" },
  ], "SKILLS", "PER-MODEL TUNING");
  assert.equal(out[0].role, "system");
  assert.match(out[0].content, /PER-MODEL TUNING/, "tuning must survive the strip");
  assert.match(out[0].content, /SKILLS/, "skills must still survive");
  assert.ok(!out.some((m) => m.content.includes("private bundled prompt")),
    "the locally-composed base prompt must still drop — the gateway sends its own");
  assert.equal(out[1].content, "build it");
  // Tuning alone, with no skills, still yields a system message.
  const tuningOnly = preserve([{ role: "system", content: "bundled" }, { role: "user", content: "x" }], "", "TUNING");
  assert.match(tuningOnly[0].content, /TUNING/);
  // Neither → no empty system message injected.
  const neither = preserve([{ role: "system", content: "bundled" }, { role: "user", content: "x" }], "", "");
  assert.equal(neither.length, 1);
  assert.equal(neither[0].role, "user");
});

test("both L0 call sites deliver per-model tuning AND the authorization framing", () => {
  // Both are composed into the dropped fullPrompt, so both must be re-added or gateway
  // models never see them. _authContextBlock is the block that stops the model over-
  // refusing legitimate security work (pentest/CTF/reverse) — losing it is why those
  // users hit walls.
  assert.match(SRC, /_l0MessagesWithSkills\(providerMessages, skillsBlock,\s*\n\s*_modelStyleTuning\(_turnConfig\.model\) \+ _authContextBlock\(\)\)/,
    "the agent path must pass tuning + auth framing");
  assert.match(SRC, /_l0MessagesWithSkills\(messages, _agentLightTurn \? "" : skillsBlock,\s*\n\s*_agentLightTurn \? "" : \(_modelStyleTuning\(config\.model\) \+ _authContextBlock\(\)\)\)/,
    "the plain-chat path must pass tuning + auth framing except on a light turn");
  assert.doesNotMatch(SRC, /_l0MessagesWithSkills\([^)]*\);(?![\s\S]{0,240}_modelStyleTuning)/,
    "no call site may drop tuning silently");
  // The framing (original vetted wording) authorizes legitimate work and keeps the line.
  const auth = extractFn("_authContextBlock");
  for (const term of ["渗透", "CTF", "逆向"]) {
    assert.ok(auth.includes(term), `auth framing must name ${term} as legitimate dev work`);
  }
  assert.match(auth, /别拒答|别说教/, "must instruct the model not to refuse or lecture");
  assert.match(auth, /攻击未授权的第三方|盗他人凭据/, "must keep the genuine harm line");
});

test("failure caches do not outlive the fact that produced them", () => {
  // A path that now exists must leave the negative cache, or the 2-strike gate refuses
  // reads of a file the agent itself just wrote.
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /if \(run\?\._failedPathAttempts\) \{[\s\S]{0,200}_failedPathAttempts\.delete/,
    "a successful mutation must clear that path's miss count");
  assert.match(loop, /\[mutationPath, actualPath, it\.call\?\.path\]/,
    "clear under every key the miss could have been recorded with");
  // The 3-strike tool memory is module-level; it must reset per run, or three invented
  // paths permanently brick read_file for the whole app session.
  assert.match(loop, /_toolFailureCounts\.clear\(\);/,
    "each run starts with a clean failure ledger");
  const clearIdx = loop.indexOf("_toolFailureCounts.clear()");
  const loopIdx = loop.indexOf("for (let iter = 0");
  assert.ok(clearIdx >= 0 && clearIdx < loopIdx, "the reset must happen before the loop starts");
});

// ---------------------------------------------------------------------------
// The verification classifier must recognise the commands real projects run.
//
// It gates TWO things: whether the plan gate lets a command through, and whether a
// green run earns verification credit. It rejected any command containing ">", so
// `npx vite build 2>&1` — which the agent writes itself — was neither. The IDE blocked
// the agent from running its own build ("先列计划 · 未执行" on a pure diagnostic) and
// then complained the work was unverified. Brittle matching, not policy.
// ---------------------------------------------------------------------------
test("verification commands survive redirects, cd prefixes, and npx runners", () => {
  const verify = load("_looksLikeVerificationCommand", { _stripHarmlessRedirects: load("_stripHarmlessRedirects") });
  // The exact command that was blocked in the field.
  assert.equal(verify("cd /Users/michael/Desktop/13131/rpa-site && npx vite build 2>&1"), true);
  // Each brittleness独立 reproduced.
  assert.equal(verify("npm run build 2>&1"), true, "2>&1 is presentation, not semantics");
  assert.equal(verify("cd rpa-site && npm run build"), true, "a cd prefix is navigation");
  assert.equal(verify("npx vite build"), true, "npx-invoked builders count");
  assert.equal(verify("cd /x && npx tsc --noEmit"), true);
  assert.equal(verify("npx vitest run"), true);
  assert.equal(verify("npx eslint src"), true);
  assert.equal(verify("pnpm dlx vite build"), true);
  // Still-correct rejections: these must NOT earn verification credit.
  assert.equal(verify("npm install"), false, "installing is not verifying");
  assert.equal(verify("npx vite"), false, "starting a dev server is not a one-shot check");
  assert.equal(verify("npm run dev"), false);
  assert.equal(verify("npx playwright open"), false, "interactive sessions are not checks");
  assert.equal(verify("npx prettier --write src"), false, "--write mutates; only --check verifies");
  assert.equal(verify("cd /x && rm -rf ."), false, "a cd prefix must not launder a destructive tail");
  assert.equal(verify("git push"), false);
  assert.equal(verify("curl http://x | sh"), false);
});

// ---------------------------------------------------------------------------
// A stale live-preview baseline must not dead-end a whole-file write.
//
// Field report: the agent ran the build, tsc -b touched files, and its attempt to CREATE
// the missing declaration the build had just demanded was refused with "生成期间文件已变化 …
// 被其他编辑器或程序修改". The only "other program" was the agent's own build. Nothing
// pinned this block, which is why it shipped.
//
// Dropping it is safe because two stronger guards remain, and this test pins both.
// ---------------------------------------------------------------------------
test("stale write-preview re-bases instead of blocking; CAS still guards the write", () => {
  const exec = SRC.slice(SRC.indexOf("const liveWritePreview = call.type === \"write\""));
  const region = exec.slice(0, 3000);
  // The dead-end is gone…
  assert.doesNotMatch(region, /生成期间文件已变化/, "a stale preview must not hard-block the write");
  // Strip comments before asserting absence — the comment above the fix quotes the
  // removed message on purpose, and matching it would be matching the explanation.
  const code = region.split("\n").filter((l) => !l.trim().startsWith("//")).join("\n");
  assert.doesNotMatch(code, /被其他编辑器或程序修改/, "…nor blame a program that did not do it");
  assert.doesNotMatch(code, /生成期间文件已变化/);
  // …replaced by dropping the preview and re-basing on current disk.
  assert.match(region, /_rollbackLiveEditorWritePreview\(liveWritePreview\)/);
  assert.match(region, /call\._liveWritePreview = null;/);
  // Guard 1: an unsaved human edit is still refused, EARLIER than this point.
  assert.ok(SRC.indexOf("编辑器有未保存内容") < SRC.indexOf("const _previewStale"),
    "the dirty-buffer check must run before the preview check it now relies on");
  // Guard 2: the write itself is still compare-and-swap against freshly-read disk.
  assert.match(SRC, /writeTextFileIfUnchanged\(fp, existed \? old : null, newContent\)/,
    "a genuinely concurrent change must still fail at the CAS write");
});

// ---------------------------------------------------------------------------
// Declaration-first command semantics (the anti-keyword architecture).
//
// The model states each command's purpose STRUCTURALLY in the tool call (an enum arg —
// structured output, not text sniffing); the harness verifies through exit codes. The
// regex classifiers survive only as a compatibility floor for models that omit the
// field, and can never overrule an explicit declaration.
// ---------------------------------------------------------------------------
test("run_cmd purpose is validated structurally and rides the call", () => {
  // The mapper has broad deps; extract just its run_cmd case and execute it.
  const m = SRC.match(/case "run_cmd": \{\s*([\s\S]*?return \{ type: "cmd"[^\n]*)/);
  assert.ok(m, "the run_cmd mapper case must exist");
  const caseFn = new Function("args", m[1].replace(/^\s*const _purpose/, "const _purpose"));
  assert.equal(caseFn({ command: "npx vite build", purpose: "verify" }).purpose, "verify");
  assert.equal(caseFn({ command: "ls" }).purpose, "", "absent declaration → empty, floor applies");
  assert.equal(caseFn({ command: "ls", purpose: "hack the gibson" }).purpose, "",
    "an invalid enum value is dropped, not trusted");
  // And the schema offers the field so models can actually declare.
  assert.match(SRC, /purpose: \{ type: "string", enum: \["explore", "verify", "install", "mutate", "scaffold", "run"\]/);
});

test("declared verify certifies on green; nothing else does", () => {
  const certifies = load("_evidenceCertifies");
  // A verification no regex could recognise now certifies.
  assert.equal(certifies({ command: "python check_invariants.py", purpose: "verify", implementationVersion: 1, ok: true }, 1), true);
  // Declared as something else → not verification, regardless of its text.
  assert.equal(certifies({ command: "node build_report.js", purpose: "run", implementationVersion: 1, ok: true }, 1), false);
  // Undeclared → not verification either. The floor is gone by design.
  assert.equal(certifies({ command: "npm run build", implementationVersion: 1, ok: true }, 1), false);
  assert.equal(certifies({ command: "python check.py", purpose: "verify", implementationVersion: 1, ok: true, exitCode: 1 }, 1), false);
});

test("declared mutate/scaffold arms accounting no classifier could see", () => {
  const mutates = load("_toolMutatesWorkspace", {
    _WORKSPACE_MUTATING_TYPES: new Set(["write"]),
    _mcpMutationHint: () => false,
  });
  // A generator invisible to any text rule, visible by declaration.
  assert.equal(mutates({ type: "cmd", command: "python generate_project.py", purpose: "mutate" }, {}), true);
  assert.equal(mutates({ type: "cmd", command: "python generate_project.py", purpose: "explore" }, {}), false);
  // …and the observed fact overrules a wrong declaration in the safe direction.
  assert.equal(mutates({ type: "cmd", command: "python generate_project.py", purpose: "explore" }, { _fsDelta: true }), true,
    "declaration adds signal, the watcher fact cannot be suppressed by it");
});

test("the checkpoint route runs with phase-scoped deadlines", () => {
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /deadlineMs: phase === "initial" \? 2800 : phase === "after_tools" \? 12000 : 8000/,
    "the initial route must fit inside its caller's 3s race");
  assert.match(SRC, /deadlineMs = 20000/,
    "the orchestrator must take the deadline as a parameter");
  assert.match(SRC, /Math\.max\(1000, deadlineMs \| 0\)/,
    "…and actually use it for the abort timer");
});

// ---------------------------------------------------------------------------
// A red build keeps the loop fixing — it does not finish on a broken tree.
//
// The screenshot bug: `tsc -b` exited nonzero (13 TS errors), the LSP never mirrored
// those errors, so the diagnostic-driven loop called the tree clean and finished. The
// build's exit code is the ground truth (Warp: terminal is where verification happens;
// Cursor: read stderr, fix, re-run; Claude Code: a failing build is information the model
// iterates on). _freshBuildFailure surfaces it from the evidence the loop already holds.
// ---------------------------------------------------------------------------
test("_freshBuildFailure finds a declared verification that exited nonzero at this edit count", () => {
  const fresh = load("_freshBuildFailure");
  const run = { _executionEvidence: [
    { purpose: "verify", command: "npm run build", exitCode: 0, implementationVersion: 2 }, // green, older
    { purpose: "run", command: "node app.js", exitCode: 1, implementationVersion: 3 },      // failed but not a verify
    { purpose: "verify", command: "tsc -b", exitCode: 2, implementationVersion: 3 },        // the real red build
  ] };
  const hit = fresh(run, 3);
  assert.ok(hit && hit.command === "tsc -b", "the newest failed verification at this edit count");
  assert.equal(hit.exitCode, 2);
  // A green build at the current edit count → nothing to block on.
  assert.equal(fresh({ _executionEvidence: [
    { purpose: "verify", command: "tsc -b", exitCode: 0, implementationVersion: 3 },
  ] }, 3), null);
  // A failure that PREDATES the latest edit is stale — the code changed since.
  assert.equal(fresh({ _executionEvidence: [
    { purpose: "verify", command: "tsc -b", exitCode: 2, implementationVersion: 1 },
  ] }, 5), null);
  // A non-verify command that failed is not a build failure (it's reviewed elsewhere).
  assert.equal(fresh({ _executionEvidence: [
    { purpose: "run", command: "node crawler.js", exitCode: 1, implementationVersion: 3 },
  ] }, 3), null);
  assert.equal(fresh({}, 1), null);
});

test("the agent loop keeps fixing a red build, bounded, then finishes honestly", () => {
  const loop = extractFn("_runAgenticLoop");
  // The build-failure signal drives a nudge + continue (keep fixing), like _diagnosticBlock.
  assert.match(loop, /const _buildFail = _freshBuildFailure\(run, _implOps\);/);
  assert.match(loop, /if \(buildFixAttempts < 6\) \{[\s\S]{0,400}_pushNudge\("buildFix"[\s\S]{0,400}continue;/,
    "a fresh red build must feed stderr back and continue, not finish");
  // Bounded: past the budget it records an honest incomplete instead of thrashing.
  assert.match(loop, /run\._incompleteReason = run\._incompleteReason \|\| "build_failing"/,
    "an unfixable build must converge to an honest incomplete");
  // The nudge carries the real exit code and stderr — facts, not a keyword guess.
  assert.match(loop, /退出码 \$\{_buildFail\.exitCode\}/);
  assert.match(loop, /_buildFail\.stderr \|\| _buildFail\.stdout/);
});

// ---------------------------------------------------------------------------
// A complete text answer ends the run — it does not get re-asked.
//
// Reported: asking the assistant a plain question produced the SAME capability answer
// twice, with a pointless list_dir on an empty folder between them. Cause, entirely in
// the loop: a text-only turn (stop_reason == "end_turn") did not end a non-mutating run,
// because _quietExitAt was 2 and any tool call resets quietTurns to 0. So answer(1) →
// forced extra turn → model makes a token tool call → counter resets → answer again.
//
// Claude Code stops on the first end_turn. Every obligation the extra turn was standing
// in for is already an explicit clause of the same exit condition.
// ---------------------------------------------------------------------------
test("a non-mutating run exits on the first quiet turn", () => {
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /const _quietExitAt = didMutate \? 4 : 1;/,
    "one complete answer must end a run that touched nothing");
  assert.doesNotMatch(loop, /const _quietExitAt = didMutate \? 4 : 2;/,
    "requiring two quiet turns is what produced the duplicated answer");
  // The counter still resets on real action — that is correct, and is precisely why a
  // threshold above 1 could be re-armed forever by token tool calls.
  assert.match(loop, /quietTurns = 0; \/\/ real action → reset the consecutive-quiet counter/);
  // The obligations are still enforced, so lowering the threshold loses no safety.
  const gate = loop.slice(loop.indexOf("if (quietTurns >= _quietExitAt"), loop.indexOf("if (quietTurns >= _quietExitAt") + 420);
  for (const clause of ["!pending", "_missingResearch.length", "_missingRequiredEffect", "_codeDeliveredUnverified"]) {
    assert.ok(gate.includes(clause), `the quiet-exit must still gate on ${clause}`);
  }
});

// ---------------------------------------------------------------------------
// Michael Design must survive a slow intent classifier.
//
// Causal chain behind "did you lose the Michael design again":
//   1. the intent classifier races an 8s timeout (main.js:17269) on the SAME upstream
//      measured at 1.8-7s with 4s header stalls;
//   2. losing that race resolves the profile to {}, so _ideSemanticProfile emits no
//      `design` flag;
//   3. the gateway gates ALL michael-design injection on semantic("design")
//      (server/src/prompts.rs), so nothing is injected for the whole run;
//   4. the late-verdict backfill exists — but was gated `!didMutate`, so the model's
//      first written file closed it permanently.
// Design knowledge is relevant for the entire UI build, so late is far better than never.
// ---------------------------------------------------------------------------
test("late intent backfill survives the first write", () => {
  const loop = extractFn("_runAgenticLoop");
  assert.match(loop, /const _lateBackfillOpen = !didMutate \|\| _implOps <= 3;/,
    "the backfill window must not be closed by the first file written");
  assert.match(loop, /if \(iter > 0 && _lateBackfillOpen && run\.engineering\?\.intentSource !== "ai"\)/,
    "backfill must re-fire for session-inherited too, not just none — that was the residual design loss");
  assert.doesNotMatch(loop, /_lateBackfillOpen && run\.engineering\?\.intentSource === "none"\)/,
    "the narrow ===none gate missed the session-inherited case");
  assert.doesNotMatch(loop, /if \(iter > 0 && !didMutate && run\.engineering\?\.intentSource === "none"\)/,
    "the old narrow window is what lost michael-design on a slow classifier");
  // The backfill now delegates to the shared helper, which refreshes the gateway profile.
  assert.match(loop, /await _applyLateIntentIfLanded\(run, config, task, session, body, _live, messages\)/,
    "the backfill must delegate to the shared late-intent apply");
  const applyLate = extractFn("_applyLateIntentIfLanded");
  assert.match(applyLate, /config\.ideSemanticProfile = _ideSemanticProfile\(run\.engineering\)/,
    "the refreshed profile must reach the gateway or the design modules stay off");
  assert.match(applyLate, /late\.intentSource !== "ai"/, "only a real (ai) late verdict may overwrite the profile");
  // Greenfield: the design decision must land BEFORE the first UI write — a bounded wait
  // on the first turn of an empty-workspace build, using the same helper.
  assert.match(loop, /iter === 0 && isAgent && run\._emptyRootAtStart && run\.engineering\?\.intentSource !== "ai"/,
    "an empty-workspace build must wait for the verdict before building the UI blind");
  assert.match(loop, /Date\.now\(\) < _intentWaitUntil[\s\S]{0,180}_applyLateIntentIfLanded/,
    "the greenfield wait must be bounded and use the shared apply");
});

test("an empty profile emits no design flag — the failure mode this guards", () => {
  const header = load("_ideSemanticProfile");
  const empty = header({});
  assert.ok(!/(^|,)design(,|$)/.test(empty.replace("2.5:", "")),
    "a timed-out classifier must not silently claim design knowledge was requested");
  const ui = header({ uiProject: true, ui: true, workspaceAction: "modify" });
  assert.match(ui, /design/, "a real UI profile does request design knowledge");
});

// ---------------------------------------------------------------------------
// A question closed with a sign-off is still a question.
//
// Reported: the assistant ended with "…想继续完善它，还是想做点别的新东西？随时说 👋"
// and the run did NOT wait — it thought again, listed the directory and batch-read five
// files. Two independent misses in _looksLikeUserQuestion:
//   1. the mark had to be the FINAL character, so any sign-off after ？ disqualified it;
//   2. no A-or-B choice shape, so a direct "X, 还是 Y？" matched no intent phrase at all.
// ---------------------------------------------------------------------------
test("_looksLikeUserQuestion: sign-offs and choice questions still pause the run", () => {
  const q = load("_looksLikeUserQuestion");
  // The exact reported closer.
  assert.equal(q("你现在桌面上有 Mr.day One 官网这个项目，想继续完善它，还是想做点别的新东西？随时说 👋"), true);
  assert.equal(q("需要我先跑一遍构建吗？随时说"), true, "a trailing sign-off must not disqualify");
  assert.equal(q("Which one do you want? let me know 😊"), true);
  assert.equal(q("用 Tailwind 还是原生 CSS？"), true, "A-or-B is a choice question by shape");
  assert.equal(q("要不要我继续？"), true);
});

test("_looksLikeUserQuestion: statements and rhetoric still do NOT pause the run", () => {
  const q = load("_looksLikeUserQuestion");
  // A new sentence after the mark means the model answered itself and is proceeding.
  assert.equal(q("要不要我继续？我这就去把构建跑完，然后把错误一条条修掉。"), false);
  assert.equal(q("Is that right? No, do X instead."), false);
  // 还是 inside a STATEMENT is not a question.
  assert.equal(q("这个项目用了 React 还是 Vue 我已经确认过了。"), false);
  assert.equal(q("这不是很明显吗？"), false, "rhetorical");
  assert.equal(q("我已经改好了。"), false);
  assert.equal(q("> 要不要继续？"), false, "quoted");
  assert.equal(q("# 要不要继续？"), false, "heading");
});

// ---------------------------------------------------------------------------
// A light turn (no tools, no project context) is unsafe with a workspace open.
//
// Reported: "这个项目是干嘛的？" in an open Rust project returned a greeting
// ("准备就绪，工作区已加载（Rust 项目）"), ~1k input tokens — it read nothing. The
// classifier had tagged projectState="none" over a real project, so the light-turn gate
// let it through. The gate now keys on the OBSERVABLE fact that a folder is open, which a
// classifier guess cannot override.
// ---------------------------------------------------------------------------
test("light turn is refused whenever a workspace folder is open", () => {
  const light = load("_shouldUseLightweightAgentTurn", { _knownWorkspaceRoots: () => [] });
  // A profile the classifier would pass as a context-free answer turn.
  const answerProfile = {
    intentSource: "ai",
    intentSemantic: { action: "answer", continuation: "new" },
    projectState: "none", deliverySurface: "answer", changeScope: "none",
    architectureMode: "none", dataStrategy: "not_applicable", researchMode: "none",
    designMode: "none", workspaceAction: "none", captureMode: "none",
    browserGoal: "none", orchestrationMode: "solo",
    runtimeObligations: [], externalObligations: [],
  };
  // No workspace open → the fast path is still allowed (its whole reason to exist).
  assert.equal(light("agent", answerProfile, {}, { workspaceOpen: false }), true);
  // A folder IS open → never light, regardless of the classifier saying projectState:none.
  assert.equal(light("agent", answerProfile, {}, { workspaceOpen: true }), false,
    "a project question must not be answered from zero context");
  // The fact overrides the guess: same 'none' profile, workspace open → full turn.
  assert.equal(light("agent", { ...answerProfile, projectState: "none" }, {}, { workspaceOpen: true }), false);
});

test("the light-turn call site passes the observable workspace fact", () => {
  assert.match(SRC, /workspaceOpen: !!String\(_earlyRoot \|\| rootPath \|\| \(workspaceRoots && workspaceRoots\[0\]\) \|\| ""\)\.trim\(\)/,
    "eligibility must be computed from the real open folder, not the profile");
});

// ---------------------------------------------------------------------------
// The first question after opening a project must get the project, not one file.
//
// Reported: "我项目是干嘛用的？" answered "基于已读取的 Cargo.toml" — it described the
// whole project from the one open manifest, never opening README/src. Cause: on a cold
// cache, _agentContextSnapshotForTurn returned only a "预热中" line + the top-level file
// list. The README, tree and key files were all still "warming up", so the model received
// nothing but the incidentally-open file. It now builds the real digest (bounded) before
// falling back to the thin snapshot.
// ---------------------------------------------------------------------------
test("cold context snapshot builds the real digest before the warming-up fallback", () => {
  const fn = extractFn("_agentContextSnapshotForTurn");
  // It must attempt the full gather, bounded by a race, on a non-empty cold workspace.
  assert.match(fn, /await Promise\.race\(\[\s*_gatherAgentContext\(query \|\| "", root\),/,
    "a cold miss must build README+tree+key-files, not just announce warming-up");
  assert.match(fn, /setTimeout\(\(\) => r\(""\), 4500\)/, "the build must be bounded so it cannot hang");
  // The real digest must be RETURNED before the thin fallback, not after it.
  const buildIdx = fn.indexOf("_gatherAgentContext(query");
  const fallbackIdx = fn.indexOf("后台上下文仍在预热");
  assert.ok(buildIdx >= 0 && buildIdx < fallbackIdx,
    "the build attempt must precede the warming-up fallback");
  // Empty workspace still short-circuits — there is nothing to build.
  assert.match(fn, /if \(!_topEmpty\) \{/, "an empty workspace must not attempt a digest build");
});

// ---------------------------------------------------------------------------
// Capture-before-mutate: a shell command's file changes become reversible.
//
// Reported: the agent ran `cd config && for f in *.json; do mv "$f" "${f%.json}.enc"`,
// renamed config files the program needs, then hand-authored a reverse mv to recover. The
// write/edit/move TOOLS are checkpointed into the run's revert-all; a run_cmd was not — the
// exact gap Cursor/Aider document. _cmdUndoPlan is the pure diff core that turns a
// before/after scope snapshot + the watcher's observed paths into exact restore steps. No
// gate, no UI — the command runs identically; only the mistake gets cheaper.
// ---------------------------------------------------------------------------
test("_cmdUndoPlan reverses the reported bulk rename exactly", () => {
  const plan = load("_cmdUndoPlan");
  const pre = new Map([["/w/config/a.json", "X"], ["/w/config/b.json", "Y"]]);
  const post = new Map([["/w/config/a.enc", "X"], ["/w/config/b.enc", "Y"]]);
  const changed = ["/w/config/a.json", "/w/config/a.enc", "/w/config/b.json", "/w/config/b.enc"];
  const steps = plan(pre, changed, post);
  const by = Object.fromEntries(steps.map((s) => [s.path, s]));
  // Recreate the .json originals from their captured content…
  assert.equal(by["/w/config/a.json"].op, "restore");
  assert.equal(by["/w/config/a.json"].existedBefore, true);
  assert.equal(by["/w/config/a.json"].contentBefore, "X");
  assert.equal(by["/w/config/a.json"].contentAfter, null);
  // …and remove the .enc files the rename created (content-matched, never a blind delete).
  assert.equal(by["/w/config/a.enc"].op, "delete");
  assert.equal(by["/w/config/a.enc"].existedBefore, false);
  assert.equal(by["/w/config/a.enc"].contentAfter, "X");
});

test("_cmdUndoPlan handles delete, overwrite, and refuses the un-snapshotted", () => {
  const plan = load("_cmdUndoPlan");
  // rm f → recreate from pre-content
  assert.deepEqual(plan(new Map([["/w/f", "keep"]]), ["/w/f"], new Map()),
    [{ path: "/w/f", existedBefore: true, contentBefore: "keep", contentAfter: null, op: "restore" }]);
  // overwrite in place → rewrite the old content back
  assert.equal(plan(new Map([["/w/f", "old"]]), ["/w/f"], new Map([["/w/f", "new"]]))[0].op, "rewrite");
  // unchanged content → no step (the command touched it but it is identical)
  assert.equal(plan(new Map([["/w/f", "s"]]), ["/w/f"], new Map([["/w/f", "s"]])).length, 0);
  // a path in NEITHER snapshot (outside captured scope) is never reversed — can't guess.
  assert.equal(plan(new Map(), ["/w/outside"], new Map()).length, 0);
  // no observed changes → empty plan, so a stale watcher can never fabricate an undo.
  assert.equal(plan(new Map([["/w/f", "x"]]), [], new Map([["/w/f", "y"]])).length, 0);
  // duplicate paths are de-duped.
  assert.equal(plan(new Map([["/w/f", "a"]]), ["/w/f", "/w/f"], new Map()).length, 1);
});

test("shell mutations are captured into the run checkpoint, bounded, never gated", () => {
  const branch = SRC.slice(SRC.indexOf('const _cmdMayMutate = call.purpose === "mutate"'));
  const region = branch.slice(0, 2500);
  // Keyed on DECLARATION or the existing risk class — not a new keyword gate.
  assert.match(region, /call\.purpose === "mutate" \|\| _commandRiskKind\(call\.command\) === "workspace-write"/);
  // Pre-snapshot before the command, post-diff after, registered into the SAME checkpoint.
  assert.match(SRC, /_preCmdSnap = await _snapshotCmdScope\(root \|\| rootPath\)/);
  assert.match(SRC, /_cmdUndoPlan\(_preCmdSnap\.files, _fsSeen\.paths, _postSnap\.files\)/);
  assert.match(SRC, /_checkpointRecord\(_cp, s\.path, s\.existedBefore, s\.contentBefore\)/);
  // Never blocks execution; a too-large scope degrades to an observed-fact note.
  assert.match(SRC, /_preCmdSnap\.truncated[\s\S]{0,400}未快照·作用域大/);
  // The bound exists so ordinary work stays cheap and node_modules is never read.
  assert.match(SRC, /_CMD_SNAPSHOT_MAX_FILES = 200/);
  assert.match(SRC, /_CMD_SNAPSHOT_MAX_BYTES = 2 \* 1024 \* 1024/);
});

// ---------------------------------------------------------------------------
// Role tool matrix: specialists get role-appropriate tools, not just prompt text.
//
// Before, every sub-agent role got the identical toolset — only _AGENT_ROLE_BLOCKS (the
// system prompt) differed. So a `design` worker couldn't open a browser to check its UI
// and a `database` worker couldn't query a db. This wires the declared role to the tools
// that role actually needs. Side-effect tools go ONLY to write workers (a read-only child
// keeps read+web), and every name/type is a real registered tool.
// ---------------------------------------------------------------------------
test("_roleCapabilities: write workers get role-matched tools, read-only get none", () => {
  const caps = load("_roleCapabilities", {
    _ROLE_CAPABILITIES: {
      frontend: { tools: ["browser", "generate_image"], types: ["browser", "genimage"] },
      design:   { tools: ["browser", "generate_image"], types: ["browser", "genimage"] },
      backend:  { tools: ["db_query", "http_request"],  types: ["db", "http"] },
      database: { tools: ["db_query"],                  types: ["db"] },
      devops:   { tools: ["docker_compose_up"],         types: ["docker_compose_up"] },
      security: { tools: ["http_request"],              types: ["http"] },
      test:     { tools: ["browser"],                   types: ["browser"] },
    },
  });
  assert.deepEqual(caps("database", true), { tools: ["db_query"], types: ["db"] });
  assert.deepEqual(caps("design", true).tools, ["browser", "generate_image"]);
  assert.deepEqual(caps("backend", true).types, ["db", "http"]);
  // Read-only child: no side-effect tools, whatever the role.
  assert.deepEqual(caps("design", false), { tools: [], types: [] });
  assert.deepEqual(caps("database", false), { tools: [], types: [] });
  // Unknown role → nothing extra (base set covers it).
  assert.deepEqual(caps("nonesuch", true), { tools: [], types: [] });
  // Every role's tool count equals its type count — a name with no admitted type would be
  // dead (dispatcher rejects it), so they must stay in lockstep.
  for (const role of ["frontend", "design", "backend", "database", "devops", "security", "test"]) {
    const c = caps(role, true);
    assert.equal(c.tools.length, c.types.length, `${role}: tools and types must be paired`);
  }
});

test("the role matrix is wired into BOTH _allow and _execTypes from one source", () => {
  const sub = extractFn("_runSubAgent");
  assert.match(sub, /const _roleCaps = _roleCapabilities\(role, write\);/);
  // name side and type side both consume the SAME _roleCaps — or a tool is visible but
  // not executable (or vice-versa).
  assert.match(sub, /for \(const t of _roleCaps\.tools\) if \(!_allow\.includes\(t\)\) _allow\.push\(t\)/);
  assert.match(sub, /for \(const t of _roleCaps\.types\) if \(!_execTypes\.includes\(t\)\) _execTypes\.push\(t\)/);
  // The matrix names must be tools the builder actually produces (verified) — guard the
  // stale "no role tool matrix" comment can't creep back as the live behavior.
  assert.doesNotMatch(sub, /不搞角色工具矩阵/);
});

// ---------------------------------------------------------------------------
// Automatic prompt optimization: the classifier restates a vague message.
//
// The user wanted terse/ambiguous input ("做个网站", "修一下") understood, not guessed at.
// The intent classifier already makes one AI call per turn; it now also emits
// semantic.restatedTask — a clarified, complete, first-person restatement — which is
// injected ALONGSIDE the raw user text (never replacing it). One field through the existing
// pipeline: zero extra latency, no keyword logic, no UI.
// ---------------------------------------------------------------------------
test("restatedTask flows through classifier schema, normalizer, and render", () => {
  // Schema advertises it, so the model fills it.
  assert.match(SRC, /"ambiguities":\[\],"restatedTask":""/, "the classifier output schema must request it");
  // Normalizer carries it, inheriting on a short continuation like the other fields.
  assert.match(SRC, /restatedTask: _aiIntentText\(rawSemantic\.restatedTask \|\| \(followsPrior \? prior\.restatedTask : ""\), 600\)/,
    "the normalizer must accept and inherit restatedTask");
  // Render injects it, and the comment fixes the invariant that it augments, not replaces.
  const render = extractFn("_agentIntentExecutionBlock");
  assert.match(render, /semantic\.restatedTask/, "the execution block must render the restatement");
  assert.match(render, /以用户原话为准/, "it must defer to the user's raw words as ground truth");
});

test("_agentIntentExecutionBlock leads with the restatement but keeps raw text authoritative", () => {
  const block = load("_agentIntentExecutionBlock", {
    _AI_INTENT_DIMENSIONS: [],
  });
  const out = block({
    intentSource: "ai",
    intentSemantic: { continuation: "new", goal: "构建产品官网", restatedTask: "帮我用 React+Vite 从零做一个产品官网，包含首屏、功能区和 CTA" },
  });
  assert.match(out, /读懂的诉求/, "a terse message gets a clarified restatement in context");
  assert.match(out, /React\+Vite 从零做一个产品官网/);
  // No restatement → no line (a clear message needs no rescue).
  const plain = block({ intentSource: "ai", intentSemantic: { continuation: "new", goal: "x" } });
  assert.doesNotMatch(plain, /读懂的诉求/);
});
